/** All translations for zizhitongjian ch.045 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑第045卷", literal: "Zizhi Tongjian, Volume 45.", idiomatic: "Zizhi Tongjian, Volume 45." },
  { zh: "【漢紀三十七】起重光作噩，盡旃蒙大淵獻，凡十五年。", literal: "【Han Records 37】 From Chongguang Zuo'e through Zhanmeng Dayuanxian—in all, fifteen years.", idiomatic: "【Han Records 37】 From the first year of the Chongguang cycle through the last year of the Zhanmeng cycle—fifteen years in all." },
  { zh: "春，帝近出觀覽城第，欲遂校獵河內；", literal: "In spring, the emperor went out nearby to view and tour city mansions, intending next to conduct a hunting drive in Henei;", idiomatic: "In spring the emperor went out to tour the capital mansions and meant next to hunt in Henei;" },
  { zh: "東平王蒼上書諫；", literal: "the Prince of Dongping, Liu Cang, memorialized in remonstrance;", idiomatic: "the Prince of Dongping, Liu Cang, sent up a memorial of remonstrance;" },
  { zh: "帝覽奏，即還宮。", literal: "the emperor read the memorial and at once returned to the palace.", idiomatic: "the emperor read it and turned back to the palace at once." },
  { zh: "秋，九月，戊寅，千乘哀王建薨，無子，國除。", literal: "In autumn, the ninth month, on the day wuyin, Prince Ai of Qiansheng died; he had no son, and the state was abolished.", idiomatic: "In autumn, in the ninth month, on wuyin day, Prince Ai of Qiansheng died without heirs, and the fief was abolished." },
  { zh: "冬，十月，乙卯，司徒郭丹、司空馮魴免，以河南尹沛國范遷為司徒，太仆伏恭為司空。", literal: "In winter, the tenth month, on the day yimao, Ministers of Education Guo Dan and of Works Feng Fang were dismissed; Henan Intendant Fan Qian of Pei was made Minister of Education, and the Grand Steward Fu Gong Minister of Works.", idiomatic: "In winter, in the tenth month, on yimao day, Ministers of Education Guo Dan and of Works Feng Fang were removed. Henan Intendant Fan Qian of Pei was appointed Minister of Education, and Grand Steward Fu Gong Minister of Works." },
  { zh: "恭，湛之兄子也。", literal: "Gong was the elder brother's son of Fu Zhan.", idiomatic: "Gong was a nephew of Fu Zhan." },
  { zh: "陵鄉侯梁松坐怨望、縣飛書誹謗，下獄死。", literal: "Marquis of Lingxiang Liang Song was charged with resentment and hanging flying letters in slander; he was cast into prison and died.", idiomatic: "Marquis of Lingxiang Liang Song was convicted of harboring resentment and posting anonymous libels. He was thrown into prison and died there." },
  { zh: "初，上為太子，太中大夫鄭興子眾以通經知名，太子及山陽王荊因梁松以縑帛請之，眾曰：「太子儲君，無外交之義。", literal: "Earlier, when the emperor was crown prince, the Grand Master of the Palace Zheng Xing's son Zhong was famed for mastering the classics; the crown prince and the Prince of Shanyang, Liu Jing, through Liang Song used silk to request him; Zhong said: \"The crown prince is the heir—there is no principle of external relations.\"", idiomatic: "Earlier, when the emperor was still crown prince, Zheng Xing's son Zhong, a Palace Grand Master famed for his mastery of the classics, was approached through Liang Song by the crown prince and Prince of Shanyang Liu Jing, who sent silk to request his teaching. Zhong said, \"The crown prince is the heir apparent. He has no business with outside ties.\"" },
  { zh: "漢有舊防，蕃王不宜私通賓客。", literal: "Han has old safeguards; feudal princes ought not privately communicate with guests.\"", idiomatic: "Han has long-standing prohibitions. A feudal prince should not traffic privately with retainers.\"" },
  { zh: "」松曰：「長者意，不可逆。", literal: "\" Song said: \"An elder's intent cannot be reversed.\"", idiomatic: "\" Song said, \"An elder's wish cannot be refused.\"" },
  { zh: "」眾曰：「犯禁觸罪，不如守正而死。", literal: "\" Zhong said: \"To violate prohibition and touch punishment is not as good as keeping to the upright and dying.\"", idiomatic: "\" Zhong said, \"Better to keep the law and die upright than break it and face punishment.\"" },
  { zh: "」遂不往。", literal: "\" He thereupon did not go.", idiomatic: "\" He refused to go." },
  { zh: "及松敗，賓客多坐之，唯眾不染於辭。", literal: "When Song fell, many guests were implicated; only Zhong was not stained in testimony.", idiomatic: "When Song fell, many of his associates were implicated. Only Zhong's testimony left him unstained." },
  { zh: "於窴王廣德將諸國兵三萬人攻莎車，誘莎車王賢，殺之，並其國。", literal: "The King of Yutian, Guangde, led troops of the various states, thirty thousand men, to attack Shache, lured the King of Shache, Xian, killed him, and annexed his state.", idiomatic: "The King of Yutian, Guangde, led thirty thousand men from the western states against Shache, lured King Xian of Shache, killed him, and annexed the kingdom." },
  { zh: "匈奴發諸國兵圍於窴，廣德請降。", literal: "The Xiongnu mobilized the various states' troops to besiege Yutian; Guangde requested surrender.", idiomatic: "The Xiongnu rallied the western states and besieged Yutian. Guangde sued for surrender." },
  { zh: "匈奴立賢質子不居征為莎車王，廣德又攻殺之，更立其弟齊黎為莎車王。", literal: "The Xiongnu established Xian's hostage son Bujuzheng as King of Shache; Guangde again attacked and killed him, and further established his younger brother Qili as King of Shache.", idiomatic: "The Xiongnu set up Xian's hostage son Bujuzheng as king of Shache. Guangde attacked again, killed him, and installed his younger brother Qili as king instead." },
  { zh: "東平王蒼自以至親輔政，聲望日重，意不自安，前後累上疏稱：「自漢興以來，宗室子弟無得在公卿位者，乞上驃騎將軍印綬，退就蕃國。", literal: "The Prince of Dongping, Cang, from being close kin in assisting government, his renown daily grew heavier; he was uneasy in mind and repeatedly memorialized, saying: \"Since Han's rise, no clansmen of the imperial house have held excellency posts—I beg to return the Rapid-as-Tigers General's seal and ribbon and withdraw to my feudal state.\"", idiomatic: "Prince of Dongping Cang, though a close kinsman who had helped govern, grew uneasy as his renown mounted. Again and again he memorialized: \"Since Han rose, no imperial clansman has held an excellency. I beg to surrender my seal and ribbon as Rapid-as-Tigers General and retire to my fief.\"" },
  { zh: "」辭甚懇切，帝乃許蒼還國，而不聽上將軍印綬。", literal: "\" His words were very earnest; the emperor thereupon permitted Cang to return to his state but did not consent to his surrendering the great general's seal and ribbon.", idiomatic: "\" His pleas were fervent. The emperor let him return to his fief but would not accept the general's seal and ribbon." },
  { zh: "春，二月，庚戌，蒼罷歸籓。", literal: "In spring, the second month, on the day gengxu, Cang was dismissed and returned to his fief.", idiomatic: "In spring, in the second month, on gengxu day, Cang left office and returned to his fief." },
  { zh: "帝以驃騎長史為東平太傅，掾為中大夫，令史為王家郎，加賜錢五千萬，布十萬匹。", literal: "The emperor made the Rapid-as-Tigers chief clerk Grand Tutor of Dongping, clerks Palace Grand Masters, clerks Royal Household Gentlemen, and added gifts of fifty million cash and one hundred thousand bolts of cloth.", idiomatic: "The emperor made his Rapid-as-Tigers chief clerk Grand Tutor of Dongping, his clerks Palace Grand Masters, and his recorders Gentlemen of the royal household, and added gifts of fifty million cash and one hundred thousand bolts of cloth." },
  { zh: "冬，十月，上行幸鄴；", literal: "In winter, the tenth month, the emperor traveled in favor to Ye;", idiomatic: "In winter, in the tenth month, the emperor traveled to Ye;" },
  { zh: "是月還宮。", literal: "that month he returned to the palace.", idiomatic: "that month he returned to the palace." },
  { zh: "十一月，北匈奴寇五原；", literal: "In the eleventh month, the Northern Xiongnu raided Wuyuan;", idiomatic: "In the eleventh month the Northern Xiongnu raided Wuyuan;" },
  { zh: "十二月，寇雲中。", literal: "in the twelfth month they raided Yunzhong.", idiomatic: "in the twelfth month they raided Yunzhong." },
  { zh: "南單于擊卻之。", literal: "The Southern Chanyu struck and repelled them.", idiomatic: "The Southern Chanyu drove them back." },
  { zh: "是歲，發遣邊民在內郡者，賜裝錢，人二萬。", literal: "This year, border people settled in inner commanderies were dispatched home; travel money was granted, twenty thousand per person.", idiomatic: "That year the court sent home border settlers living in the inner commanderies and gave each person twenty thousand in travel funds." },
  { zh: "安豐戴侯竇融年老，子孫縱誕，多不法。", literal: "Marquis Dai of Anfeng, Dou Rong, was aged; his sons and grandsons were licentious and unrestrained, and many acts were unlawful.", idiomatic: "Marquis Dai of Anfeng, Dou Rong, had grown old. His sons and grandsons ran wild, and their crimes were many." },
  { zh: "長子穆尚內黃公主。", literal: "His eldest son Mu had married the Princess of Neihuang.", idiomatic: "His eldest son Mu had married the Princess of Neihuang." },
  { zh: "矯稱陰太后詔，令六安侯劉盱去婦，以女妻之。", literal: "He falsely claimed an edict of Empress Dowager Yin, ordering Marquis of Liu'an Liu Xu to put away his wife and marry Mu's daughter to him.", idiomatic: "He forged an edict in Empress Dowager Yin's name ordering Marquis of Liu'an Liu Xu to divorce his wife and take Mu's daughter in marriage." },
  { zh: "盱婦家上書言狀，帝大怒。", literal: "Xu's wife's family memorialized the facts; the emperor was greatly enraged.", idiomatic: "Xu's wife's kin reported the affair to the throne. The emperor flew into a rage." },
  { zh: "盡免穆等官，諸竇為郎吏者，皆將家屬歸故郡，獨留融京師；", literal: "Mu and the rest were wholly removed from office; all the Dou who served as Gentlemen or clerks were sent with their households back to their native commanderies; only Rong was kept in the capital;", idiomatic: "Mu and his kin were stripped of every office. Every Dou serving as a Gentleman or clerk was sent home with his household to his native commandery. Only Rong was kept in the capital;" },
  { zh: "融尋薨。", literal: "Rong soon died.", idiomatic: "Rong soon died." },
  { zh: "後數歲，穆等復坐事與子勳、宣皆下獄死。", literal: "Several years later Mu and the rest again were implicated in affairs; with sons Xun and Xuan they were all cast into prison and died.", idiomatic: "Years later Mu and his brothers were implicated again. Mu, his sons Xun and Xuan, all went to prison and died." },
  { zh: "久之，詔還融夫人與小孫一人居雒陽。", literal: "After a long time, an edict returned Rong's wife and one young grandson to dwell in Luoyang.", idiomatic: "Long afterward an edict allowed Rong's wife and one young grandson to live again in Luoyang." },
  { zh: "春，二月，王雒山出寶鼎，獻之。", literal: "In spring, the second month, Mount Wang Luo produced a precious tripod; it was presented.", idiomatic: "In spring, in the second month, a precious tripod emerged on Mount Wang Luo and was presented to the throne." },
  { zh: "夏，四月，甲子，詔曰：「祥瑞之降，以應有德；", literal: "In summer, the fourth month, on the day jiazi, an edict said: \"The descent of auspicious omens is to answer to those with virtue;\"", idiomatic: "In summer, in the fourth month, on jiazi day, an edict ran: \"Auspicious omens descend only upon the virtuous;\"" },
  { zh: "方今政化多僻，何以致茲！", literal: "\"yet now governance and transformation are largely crooked—how could this be attained!\"", idiomatic: "\"yet our governance is full of crooked paths. How could such a sign appear?\"" },
  { zh: "《易》曰：『鼎像三公，』豈公卿奉職得其理邪！", literal: "\"The Changes says, 'The tripod images the Three Excellencies'—have the excellencies and ministers fulfilled their duties with proper reason!\"", idiomatic: "\"The Changes says, 'The tripod images the Three Excellencies.' Have our ministers discharged their duties as they should?\"" },
  { zh: "其賜三公帛五十匹，九卿、二千石半之。", literal: "\"Let the Three Excellencies each be granted fifty bolts of silk; the Nine Ministers and those of two-thousand-dan rank receive half.\"", idiomatic: "\"Grant the Three Excellencies fifty bolts of silk each, and half that to the Nine Ministers and officials of two-thousand-dan rank.\"" },
  { zh: "先帝詔書，禁人上事言聖，而間者章奏頗多浮詞；", literal: "\"The former emperor's edict forbade people from submitting matters calling the ruler sage, yet recently memorials have largely been empty words;\"", idiomatic: "\"The late emperor forbade memorials that called the ruler a sage, yet lately the court has been flooded with empty flattery;\"" },
  { zh: "自今若有過稱虛譽，尚書皆宜抑而不省，示不為諂子蚩也。", literal: "\"from now on if there is excessive praise or false glory, the Secretariat should all suppress and not forward them, to show one is not a flattering son or a corrupter.\"", idiomatic: "\"hereafter the Secretariat must suppress and not forward any memorial of excessive or false praise, to show that flatterers and sycophants will not be indulged.\"" },
  { zh: "冬，十月，上行幸魯；", literal: "In winter, the tenth month, the emperor traveled in favor to Lu;", idiomatic: "In winter, in the tenth month, the emperor traveled to Lu;" },
  { zh: "十二月，還幸陽城；", literal: "in the twelfth month he returned in favor to Yangcheng;", idiomatic: "in the twelfth month he turned back by way of Yangcheng;" },
  { zh: "壬午，還宮。", literal: "on the day renwu he returned to the palace.", idiomatic: "on renwu day he returned to the palace." },
  { zh: "是歲，南單于適死，單于莫之子蘇立，為丘除車林鞮單于；", literal: "This year the Southern Chanyu Shi died; the chanyu's son Mo's son Su was established as Chanyu Qiuchu Chelindi;", idiomatic: "That year Southern Chanyu Shi died. Mo's son Su was raised as Chanyu Qiuchu Chelindi;" },
  { zh: "數月，復死，單于適之弟長立，為湖邪屍逐侯鞮單于。", literal: "several months later he again died; Shi's younger brother Chang was established as Chanyu Huye Shizhu Hou Di.", idiomatic: "within months he too died. Shi's younger brother Chang was raised as Chanyu Huye Shizhu Hou Di." },
  { zh: "春，正月，癸卯，皇太后陰氏崩。", literal: "In spring, the first month, on the day guimao, Empress Dowager of the Yin clan died.", idiomatic: "In spring, in the first month, on guimao day, Empress Dowager Yin died." },
  { zh: "二月，庚申，葬光烈皇后。", literal: "In the second month, on the day gengshen, Empress Guanglie was buried.", idiomatic: "In the second month, on gengshen day, Empress Guanglie was buried." },
  { zh: "北匈奴猶盛，數寇邊，遣使求合市；", literal: "The Northern Xiongnu were still strong and repeatedly raided the border; they sent envoys requesting joint markets;", idiomatic: "The Northern Xiongnu were still strong and raided the frontier again and again. They sent envoys to ask for border markets;" },
  { zh: "上冀其交通，不復為寇，許之。", literal: "the emperor hoped that through intercourse they would no longer raid, and granted it.", idiomatic: "the emperor hoped trade would keep them from raiding and agreed." },
  { zh: "以東海相宋均為尚書令。", literal: "Song Jun, Chancellor of Donghai, was made Director of the Masters of Writing.", idiomatic: "Song Jun, Chancellor of Donghai, was appointed Director of the Masters of Writing." },
  { zh: "初，均為九江太守，五日一聽事，悉省掾、史，閉督郵府內，屬縣無事，百姓安業。", literal: "Earlier, when Jun was Administrator of Jiujiang, he heard cases once every five days, wholly reduced clerks and recorders, closed the inspector-post office within, and the subordinate counties had no affairs—the common people settled in their occupations.", idiomatic: "Earlier, as Administrator of Jiujiang, Jun held court once every five days, cut back his clerks and recorders, and shut the inspector's office. The subordinate counties had little to do, and the people lived in peace." },
  { zh: "九江舊多虎暴，常募設檻阱，而猶多傷害。", literal: "Jiujiang had long had many violent tigers; they constantly recruited men to set cages and pits, yet still there were many injuries.", idiomatic: "Jiujiang had long been plagued by man-eating tigers. The commandery constantly hired men to set traps, yet people were still mauled." },
  { zh: "均下記屬縣曰：「夫江、淮之有猛獸，猶北土之有雞豚也，今為民害，咎在殘吏，而勞勤張捕，非憂恤之本也。", literal: "Jun sent notice down to the subordinate counties saying: \"That the Yangzi and Huai have fierce beasts is like the northern lands having chickens and pigs—now they harm the people; the fault lies in cruel clerks, while toiling in spreading capture is not the root of compassionate care.\"", idiomatic: "Jun sent instructions to the counties: \"Fierce beasts along the Yangzi and Huai are no stranger than chickens and pigs in the north. When they harm the people, the fault lies with brutal officials, not with the beasts. To exhaust the people with round after round of hunting is no way to show care.\"" },
  { zh: "其務退奸貪，思進忠善，可一去檻阱，除削課制。", literal: "\"Their task is to dismiss the treacherous and greedy and think to advance the loyal and good—cages and pits may all be removed, and the levies and regulations cut away.\"", idiomatic: "\"Drive out the corrupt and greedy, promote the loyal and good, remove every trap, and abolish the hunting quotas.\"" },
  { zh: "」其後無復虎患。", literal: "\" Afterward there was no further tiger trouble.", idiomatic: "\" After that the tiger plague ceased." },
  { zh: "帝聞均名，故任以樞機。", literal: "The emperor heard Jun's name and for this entrusted him with the pivot of state.", idiomatic: "The emperor had heard of Jun's reputation and for that placed him at the heart of government." },
  { zh: "均謂人曰：「國家喜文法、廉吏，以為足止奸也；", literal: "Jun said to others: \"The state delights in written law and incorrupt clerks, holding that these suffice to stop wickedness;\"", idiomatic: "Jun told others, \"The court loves written law and incorrupt officials and thinks that is enough to stop crime;\"" },
  { zh: "然文吏習為欺謾，而廉吏清在一己，無益百姓流亡、盜賊為害也。", literal: "\"yet clerks versed in documents are practiced in deception, while incorrupt clerks are clean only in themselves—this does not help the common people wandering in exile or bandits doing harm.\"", idiomatic: "\"yet clerks trained in documents only learn to deceive, and an incorrupt man may keep himself clean while the people flee and bandits run wild.\"" },
  { zh: "均欲叩頭爭之，時未可改也，久將自苦之，乃可言耳！", literal: "\"Jun wished to knock his head and dispute it, but the time was not yet fit for change; in time the state itself would suffer for it—only then might one speak!\"", idiomatic: "\"Jun meant to argue the point to the emperor's face, but the time was not ripe. In time the court would suffer for it—only then would words avail.\"" },
  { zh: "」未及言，會遷司隸校尉。", literal: "\" Before he could speak, it happened he was transferred to Colonel of the Metropolitan Area.", idiomatic: "\" Before he could speak, he was transferred to Colonel of the Metropolitan Area." },
  { zh: "後上聞其言，追善之。", literal: "Later the emperor heard his words and retrospectively approved them.", idiomatic: "Later the emperor heard what he had said and praised it in retrospect." },
  { zh: "春，正月，己卯，司徒范遷薨。", literal: "In spring, the first month, on the day jimao, Minister of Education Fan Qian died.", idiomatic: "In spring, in the first month, on jimao day, Minister of Education Fan Qian died." },
  { zh: "三月，辛卯，以太尉虞延為司徒，衛尉趙熹行太尉事。", literal: "In the third month, on the day xinmao, Grand Commandant Yu Yan was made Minister of Education, and Commandant of the Guards Zhao Xi acted as Grand Commandant.", idiomatic: "In the third month, on xinmao day, Grand Commandant Yu Yan was appointed Minister of Education, and Commandant of the Guards Zhao Xi acted as Grand Commandant." },
  { zh: "越騎司馬鄭眾使北匈奴，單于欲令眾拜，眾不為屈。", literal: "Major of the Exalted Cavalry Zheng Zhong was envoy to the Northern Xiongnu; the chanyu wished to make Zhong bow, and Zhong would not bend.", idiomatic: "Major of the Exalted Cavalry Zheng Zhong went as envoy to the Northern Xiongnu. The chanyu demanded that he bow. Zhong would not yield." },
  { zh: "單于圍守，閉之不與水火；", literal: "The chanyu besieged and guarded him, shutting him in and giving neither fire nor water;", idiomatic: "The chanyu surrounded his lodging and cut off fire and water;" },
  { zh: "眾拔刀自誓，單于恐而止，乃更發使，隨眾還京師。", literal: "Zhong drew his blade and swore upon himself; the chanyu feared and stopped, then further sent an envoy to accompany Zhong back to the capital.", idiomatic: "Zhong drew his sword and swore to die rather than submit. The chanyu, afraid, relented and sent another envoy to escort him back to the capital." },
  { zh: "初，大司農耿國上言：「宜置度遼將軍屯五原，以防南匈奴逃亡。", literal: "Earlier, the Grand Minister of Agriculture Geng Guo memorialized: \"One ought to establish a General Who Crosses the Liao garrisoned at Wuyuan to guard against the Southern Xiongnu fleeing.\"", idiomatic: "Earlier Grand Minister of Agriculture Geng Guo had memorialized, \"We should post a General Who Crosses the Liao at Wuyuan to block any flight of the Southern Xiongnu.\"" },
  { zh: "」朝廷不從，南匈奴須卜骨都侯等知漢與北虜交使，內懷嫌怨，欲畔，密使人詣北虜，令遣兵迎之。", literal: "\" The court did not follow this. The Southern Xiongnu Xubu Gudu Marquis and others, learning that Han and the northern foe exchanged envoys, harbored suspicion and resentment inwardly, wished to rebel, and secretly sent men to the northern foe to have them dispatch troops to welcome them.", idiomatic: "\" The court had not listened. When the Southern Xiongnu Xubu Gudu Marquis and others learned that Han and the northern Xiongnu were exchanging envoys, they nursed suspicion and planned rebellion, secretly sending men north to ask for troops to receive them." },
  { zh: "鄭眾出塞，疑有異；", literal: "Zheng Zhong went beyond the frontier and suspected something amiss;", idiomatic: "Zheng Zhong, leaving the frontier, sensed something wrong;" },
  { zh: "伺候，果得須卜使人。", literal: "he watched and waited, and indeed seized the Xubu envoy.", idiomatic: "he kept watch and indeed seized the Xubu envoy." },
  { zh: "乃上言：「宜更置大將，以防二虜交通。", literal: "He thereupon memorialized: \"One ought further to establish a great general to guard against the two foes communicating.\"", idiomatic: "He memorialized, \"We should appoint a great commander to block collusion between the two Xiongnu powers.\"" },
  { zh: "」由是始置度遼營，以中郎將吳棠行度遼將軍事，將黎陽虎牙營士屯五原曼柏。", literal: "\" From this the Crossing-the-Liao camp was first established; Palace Gentleman Wu Tang acted as General Who Crosses the Liao, leading the Tiger's-Fang troops of Liyang to garrison at Manbo in Wuyuan.", idiomatic: "\" Thereupon the Crossing-the-Liao camp was established. Palace Gentleman Wu Tang acted as General Who Crosses the Liao, leading the Tiger's-Fang troops of Liyang to garrison at Manbo in Wuyuan." },
  { zh: "秋，郡國十四大水。", literal: "In autumn, fourteen commanderies and states suffered great floods.", idiomatic: "In autumn fourteen commanderies and kingdoms were struck by great floods." },
  { zh: "冬，十月，北宮成。", literal: "In winter, the tenth month, the Northern Palace was completed.", idiomatic: "In winter, in the tenth month, the Northern Palace was completed." },
  { zh: "丙子，募死罪系囚詣度遼營；", literal: "On the day bingzi, prisoners held on capital charges were recruited to the Crossing-the-Liao camp;", idiomatic: "On bingzi day the court recruited prisoners under sentence of death for the Crossing-the-Liao camp;" },
  { zh: "有罪亡命者，令贖罪各有差。", literal: "those guilty and fugitive from punishment were ordered to redeem guilt each according to rank.", idiomatic: "fugitives under sentence were allowed to redeem their crimes by degrees." },
  { zh: "楚王英奉黃縑、白紈詣國相曰：「托在籓輔，過惡累積，歡喜大恩，奉送縑帛，以贖愆罪。", literal: "The Prince of Chu, Ying, presented yellow silk and white fine silk to the kingdom chancellor, saying: \"Entrusted in frontier support, faults and evils have piled up; I rejoice in great grace and present silk to redeem my offenses.\"", idiomatic: "Prince of Chu Ying sent yellow silk and white gauze to his kingdom chancellor, saying, \"Entrusted to the frontier as a vassal, I have piled up faults. Grateful for the throne's grace, I offer this silk to redeem my offenses.\"" },
  { zh: "」國相以聞。", literal: "\" The chancellor reported it upward.", idiomatic: "\" The chancellor reported it to the throne." },
  { zh: "詔報曰：「楚王誦黃、老之微言，尚浮屠之仁祠，潔齊三月，與神為誓，何嫌何疑，當有悔吝！", literal: "The edict in reply said: \"The Prince of Chu recites the subtle words of Huang-Lao, esteems the benevolent rites of the Buddha, keeps pure fast for three months, and makes oath with the spirits—what suspicion, what doubt, that there should be regret!\"", idiomatic: "The edict in reply said, \"Prince of Chu recites the subtle teachings of Huang-Lao, honors the Buddha's compassionate rites, keeps three months of purification, and makes oath to the spirits. What suspicion remains? What need for regret?\"" },
  { zh: "其還贖，以助伊蒲塞、桑門之盛饌。", literal: "\"Return the redemption and use it to aid the great feast of Yupusai and the shramanas.\"", idiomatic: "\"Return his gift and let it supply the feast of Yupusai and the monks.\"" },
  { zh: "」初，帝聞西域有神，其名曰佛，因遣使之天竺求其道，得其書及沙門以來。", literal: "\" Earlier, the emperor heard that in the Western Regions there was a spirit whose name was Buddha; he thereupon sent envoys to Tianzhu to seek its Way, obtained its books and shramanas, and brought them.", idiomatic: "\" Earlier the emperor had heard that the Western Regions held a god named Buddha. He sent envoys to Tianzhu to seek its Way and brought back its scriptures and monks." },
  { zh: "其書大抵以虛無為宗，貴慈悲不殺；", literal: "Its books largely took emptiness and nonbeing as their root and prized compassion and not killing;", idiomatic: "Its scriptures chiefly take emptiness as their root and prize compassion and abstention from killing;" },
  { zh: "以為人死，精神不滅，隨復受形；", literal: "they held that when a man dies his spirit is not extinguished but follows to receive form again;", idiomatic: "they hold that when a man dies his spirit does not perish but takes form again;" },
  { zh: "生時所行善惡，皆有報應，故所貴修練精神，以至為佛；", literal: "good and evil done in life all have corresponding retribution; therefore what they prize is cultivating and refining the spirit until one becomes Buddha;", idiomatic: "good and evil done in life all meet with retribution; therefore they prize the cultivation of spirit until one becomes Buddha;" },
  { zh: "善為宏闊勝大之言以勸誘愚俗。", literal: "they are skilled in broad and surpassing words to exhort and entice the foolish multitude.", idiomatic: "they are skilled in vast and lofty speech to win over the common crowd." },
  { zh: "精於其道者，號曰沙門。", literal: "Those refined in its Way are styled shramanas.", idiomatic: "Those accomplished in the Way are called shramanas." },
  { zh: "於是中國始傳其術，圖其形像，而王公貴人，獨楚王英最先好之。", literal: "From this the central states first transmitted its art and drew its images; among kings, dukes, and the noble, only the Prince of Chu, Ying, was first to delight in it.", idiomatic: "From then on the central realm began to spread the teaching and depict its images. Among kings and nobles, only Prince of Chu Ying took it up first." },
  { zh: "壬寅晦，日有食之，既。", literal: "On the last day of the cycle, renyin, there was an eclipse of the sun—it was total.", idiomatic: "On the last day of the month, renyin, the sun was wholly eclipsed." },
  { zh: "詔群司勉修職事，極言無諱。", literal: "An edict ordered the various offices to strive in fulfilling duties and speak to the limit without taboo.", idiomatic: "An edict ordered every office to fulfill its duties and speak without reserve." },
  { zh: "於是在位者皆上封事，各言得失；", literal: "Thereupon those in office all submitted sealed memorials, each speaking of gains and losses;", idiomatic: "Thereupon every official submitted sealed memorials, each speaking of what had gone wrong;" },
  { zh: "帝覽章，深自引咎，以所上班示百官。", literal: "the emperor reviewed the memorials, deeply blamed himself, and displayed to the hundred offices what had been submitted.", idiomatic: "the emperor read them, took deep blame upon himself, and showed the memorials to the whole bureaucracy." },
  { zh: "詔曰：「群僚所言，皆朕之過。", literal: "An edict said: \"What the host of ministers spoke—all are Our faults.\"", idiomatic: "An edict said, \"Everything my ministers have said is Our fault.\"" },
  { zh: "民冤不能理，吏黠不能禁；", literal: "\"The people's grievances cannot be settled, clerks' cunning cannot be forbidden;\"", idiomatic: "\"The people's wrongs go unredressed, and cunning clerks go unchecked;\"" },
  { zh: "而輕用民力，繕修宮宇，出入無節，喜怒過差。", literal: "\"yet We lightly use the people's strength, repair and build palaces and halls, go in and out without measure, and joy and anger exceed their bounds.\"", idiomatic: "\"We have wasted the people's labor on palaces, come and gone without restraint, and let joy and anger run too far.\"" },
  { zh: "永覽前戒，辣然兢懼；", literal: "\"Forever viewing former warnings, We are stung and fearful with care;\"", idiomatic: "\"We take the old warnings to heart and tremble with fear;\"" },
  { zh: "徒恐薄德，久而致怠耳！", literal: "\"only fearing thin virtue—in time leading to slackness!\"", idiomatic: "\"only fearing that shallow virtue will in time breed neglect!\"" },
  { zh: "北匈奴雖遣使入貢，而寇鈔不息，邊城晝閉。", literal: "The Northern Xiongnu, though they sent envoys to enter with tribute, did not cease raiding and plunder; border cities closed their gates by day.", idiomatic: "Though the Northern Xiongnu sent tribute envoys, their raids never ceased and frontier cities shut their gates even by day." },
  { zh: "帝議遣使報其使者，鄭眾上疏諫曰：「臣聞北單于所以要致漢使者，欲以離南單于之眾，堅三十六國之心也；", literal: "The emperor deliberated sending envoys to reply to their envoys; Zheng Zhong submitted a memorial remonstrating, saying: \"Your servant has heard that the reason the Northern Chanyu wants to summon Han envoys is to divide the Southern Chanyu's masses and firm the hearts of the thirty-six states;\"", idiomatic: "The emperor considered sending envoys to answer theirs. Zheng Zhong submitted a memorial of remonstrance: \"I have heard that the Northern Chanyu wants Han envoys in order to divide the Southern Chanyu's followers and stiffen the resolve of the thirty-six states;\"" },
  { zh: "又當揚漢和親，誇示鄰敵，令西域欲歸化者局足狐疑，懷土之人絕望中國耳。", literal: "\"Moreover he would proclaim Han marriage alliance, boast to neighboring foes, make those in the Western Regions who wish to submit hesitate on tiptoe in doubt, and men who cherish their land despair of China.\"", idiomatic: "\"he would proclaim Han marriage alliances, boast to neighboring enemies, make Western Regions peoples who wish to submit hesitate in doubt, and those who yearn for China lose hope.\"" },
  { zh: "漢使既到，便偃蹇自信；", literal: "\"Once Han envoys arrive, he will at once be arrogant and self-assured;\"", idiomatic: "\"Once Han envoys arrive, he will grow arrogant and self-assured;\"" },
  { zh: "若復遣之，虜必自謂得謀，其群臣駁議者不敢復言。", literal: "\"if we send them again, the barbarians will surely think they have got their scheme, and among his ministers those who disputed will not dare speak again.\"", idiomatic: "\"if we send them again, the barbarians will think their scheme has succeeded, and ministers who objected will not dare speak again.\"" },
  { zh: "如是，南庭動搖，烏桓有離心矣。", literal: "\"Thus the southern court will be shaken, and the Wuhuan will have a mind to separate.\"", idiomatic: "\"Thus the southern court will waver and the Wuhuan will turn away.\"" },
  { zh: "南單于久居漢地，具知形勢，萬分離析，旋為邊害。", literal: "\"The Southern Chanyu has long dwelt in Han territory and fully knows the situation; if he splits into ten thousand parts, he will at once become a border harm.\"", idiomatic: "\"The Southern Chanyu has long lived in Han territory and knows our situation well. If he splits apart, he will soon become a border menace.\"" },
  { zh: "今幸有度遼之眾揚威北垂，雖勿報答，不敢為患。", literal: "\"Now fortunately there are the Crossing-Liao troops displaying might on the northern border; even if we do not reply, they will not dare become a trouble.\"", idiomatic: "\"Fortunately the Crossing-Liao army now displays might on the northern frontier. Even without a reply, they will not dare make trouble.\"" },
  { zh: "」帝不從，復遣眾往。", literal: "\" The emperor did not follow this and again sent Zhong.", idiomatic: "\" The emperor did not agree and again sent Zhong." },
  { zh: "眾因上言：「臣前奉使，不為匈奴拜，單于恚恨。", literal: "Zhong thereupon submitted: \"Your servant on a former mission did not bow to the Xiongnu; the chanyu was angry and resentful.", idiomatic: "Zhong then submitted: \"On my former mission I did not bow to the Xiongnu. The chanyu was furious." },
  { zh: "遣兵圍臣；", literal: "He sent troops to surround your servant;", idiomatic: "He sent troops to surround me;" },
  { zh: "今復銜命，必見陵折，臣誠不忍持大漢節對氈裘獨拜，如令匈奴遂能服臣，將有損大漢之強。", literal: "now again bearing orders, I will surely be insulted and broken; your servant truly cannot bear to hold the great Han staff of office and bow alone before felt robes—if the Xiongnu should thereby make your servant submit, it will harm the strength of great Han.\"", idiomatic: "now sent again on orders, I will surely be humiliated. I truly cannot bear to hold the great Han staff and bow alone before felt-robed barbarians. If the Xiongnu could thereby make me submit, it would weaken great Han.\"" },
  { zh: "」帝不聽。", literal: "\" The emperor would not listen.", idiomatic: "\" The emperor would not listen." },
  { zh: "眾不得已，既行，在路連上書固爭之；", literal: "Zhong had no choice; once he had set out, on the road he repeatedly submitted memorials firmly disputing it;", idiomatic: "Zhong had no choice. Once underway he repeatedly submitted memorials arguing the point;" },
  { zh: "詔切責眾，追還，系廷尉，會赦，歸家。", literal: "an edict sharply rebuked Zhong, recalled him, bound him in the Court Commandant's office; there happened to be an amnesty, and he returned home.", idiomatic: "an edict sharply rebuked Zhong, recalled him, and bound him over to the Court Commandant. An amnesty followed and he went home." },
  { zh: "其後帝見匈奴來者，聞眾與單于爭禮之狀，乃復召眾為軍司馬。", literal: "Afterward when the emperor saw Xiongnu visitors and heard how Zhong had disputed ritual with the chanyu, he again summoned Zhong as Army Major.", idiomatic: "Later, when the emperor saw Xiongnu visitors and heard how Zhong had disputed ritual with the chanyu, he summoned Zhong back as Army Major." },
  { zh: "夏，四月，甲辰，詔司隸校尉、部刺史歲上墨綬長吏視事三歲已上、治狀尤異者各一人與計偕上，及尤不治者亦以聞。", literal: "In summer, the fourth month, on the day jiachen, an edict ordered the Director of the Masters of Writing and the regional inspectors yearly to submit one chief official of black-cord rank who had held office three years or more and whose governance was especially outstanding, to come up with the annual accounts, and also to report those especially poorly governed.", idiomatic: "In summer, in the fourth month, on jiachen day, an edict ordered the Director of the Masters of Writing and regional inspectors each year to send up one black-cord chief official who had served three years or more with especially outstanding governance, to come with the annual accounts, and also to report those especially poorly governed." },
  { zh: "是歲，大有年。", literal: "This year there was a great harvest.", idiomatic: "That year the harvest was abundant." },
  { zh: "賜皇子恭號曰靈壽王，黨號曰重熹王，未有國邑。", literal: "The emperor's sons Gong was titled King of Lingshou and Dang King of Chongxi; neither yet had a state fief.", idiomatic: "The princes Gong and Dang were titled Kings of Lingshou and Chongxi; neither yet had a state fief." },
  { zh: "帝崇尚儒學，自皇太子、諸王侯及大臣子弟、功臣子孫，莫不受經。", literal: "The emperor honored Confucian learning; from the heir apparent, the various kings and marquises, and the sons of great ministers and meritorious officials' descendants, none failed to receive the classics.", idiomatic: "The emperor honored Confucian learning. From the heir apparent and the various kings and marquises to ministers' sons and meritorious officials' descendants, all studied the classics." },
  { zh: "又為外戚樊氏、郭氏、陰氏、馬氏諸子立學於南宮，號「四姓小侯」。", literal: "He also established a school in the Southern Palace for the sons of the consort kin clans Fan, Guo, Yin, and Ma, called \"the Four Clans Junior Marquises.\"", idiomatic: "He also founded a school in the Southern Palace for sons of the Fan, Guo, Yin, and Ma consort clans, called \"the Four Clans Junior Marquises.\"" },
  { zh: "置《五經》師，搜選高能以授其業。", literal: "He set up teachers of the Five Classics and searched out men of high ability to transmit their studies.", idiomatic: "He appointed teachers of the Five Classics and selected men of high ability to instruct them." },
  { zh: "自期門、羽林之士，悉令通《孝經》章句。", literal: "From the Palace Gate and Feathered Forest guardsmen, all were ordered to master the chapters and sentences of the Classic of Filial Piety.", idiomatic: "Even Palace Gate and Feathered Forest guardsmen were all required to master the Classic of Filial Piety." },
  { zh: "匈奴亦遣子入學。", literal: "The Xiongnu also sent a son to study.", idiomatic: "The Xiongnu also sent a son to study at court." },
  { zh: "廣陵王荊復呼相工謂曰：「我貌類先帝，先帝三十得天下，我今亦三十，可起兵未？", literal: "The King of Guangling, Jing, again summoned a physiognomist and said: \"My appearance resembles the late emperor; the late emperor at thirty obtained the realm—I too am now thirty—may I raise troops or not?\"", idiomatic: "The King of Guangling, Jing, again summoned a physiognomist and said, \"I look like the late emperor. He obtained the realm at thirty, and I too am thirty. May I raise troops?\"" },
  { zh: "」相者詣吏告之，荊惶恐，自繫獄，帝加恩，不考極其事，詔不得臣屬吏民，唯食租如故，使相、中尉謹宿衛之。", literal: "\" The physiognomist went to the officials and reported him; Jing was fearful and alarmed and bound himself in prison; the emperor showed added grace, did not investigate the matter to the limit, ordered that he must not retain officials or commoners as subjects, only receive rent as before, and had the chancellor and the Commandant of the Capital guard him carefully.", idiomatic: "\" The physiognomist reported him to the authorities. Jing in terror imprisoned himself. The emperor showed mercy, did not press the matter to the limit, ordered that he must not retain officials or commoners as subjects, receive only his rent as before, and had the chancellor and the Commandant of the Capital guard him closely." },
  { zh: "荊又使巫祭祀、祝詛。", literal: "Jing again had shamans perform sacrifices and curse.", idiomatic: "Jing again had shamans sacrifice and curse." },
  { zh: "詔長水校尉樊鯈等雜治其獄，事竟，奏請誅刑。", literal: "An edict ordered Chief of the Long River Fan Chuo and others jointly to try his case; when the matter was concluded they memorialized requesting execution.", idiomatic: "An edict ordered Chief of the Long River Fan Chuo and others jointly to try his case. When it was concluded they memorialized requesting execution." },
  { zh: "帝怒曰；", literal: "The emperor said angrily:", idiomatic: "The emperor said angrily:" },
  { zh: "「諸卿以我弟故，欲誅之。", literal: "\"You gentlemen, because he is my younger brother, wish to execute him.", idiomatic: "\"You gentlemen wish to execute him because he is my younger brother." },
  { zh: "即我子，卿等敢爾邪？", literal: "If it were my son, would you gentlemen dare thus?\"", idiomatic: "If it were my son, would you dare thus?\"" },
  { zh: "」鯈對曰：「天下者高帝天下，非陛下之天下也。", literal: "\" Chuo replied: \"The realm is the High Emperor's realm, not Your Majesty's realm.\"", idiomatic: "\" Chuo replied, \"The realm is the High Emperor's realm, not Your Majesty's realm alone.\"" },
  { zh: "《春秋》之義，君親無將，將而必誅。", literal: "\"The meaning of the Spring and Autumn Annals is: between ruler and kin there is no commander-in-chief—if one becomes commander-in-chief, he must be executed.\"", idiomatic: "\"The Spring and Autumn Annals teach that between ruler and kin there is no commander-in-chief—if one becomes such, he must be executed.\"" },
  { zh: "臣等以荊屬托母弟，陛下留聖心，加惻隱，故敢請耳；", literal: "\"Your servants, because Jing is entrusted as a younger brother of the same mother, and Your Majesty retains a sage heart and adds compassion, therefore dared only to request it;", idiomatic: "\"We asked only because Jing is Your Majesty's uterine younger brother and Your Majesty retains compassion;\"" },
  { zh: "如令陛下子，臣等專誅而已。", literal: "\"if it were Your Majesty's son, your servants would execute him on our own authority.\"", idiomatic: "\"if it were Your Majesty's son, we would execute him on our own authority.\"" },
  { zh: "」帝歎息善之。", literal: "\" The emperor sighed and approved this.", idiomatic: "\" The emperor sighed and approved." },
  { zh: "鯈，宏之子也。", literal: "Chuo was the son of Hong.", idiomatic: "Chuo was the son of Fan Hong." },
  { zh: "春，二月，廣陵思王荊自殺，國除。", literal: "In spring, the second month, the Reflective King of Guangling, Jing, killed himself; the state was abolished.", idiomatic: "In spring, in the second month, the Reflective King of Guangling, Jing, killed himself and the state was abolished." },
  { zh: "夏，四月，戊子，赦天下。", literal: "In summer, the fourth month, on the day wuzi, there was an amnesty for the realm.", idiomatic: "In summer, in the fourth month, on wuzi day, the realm was amnestied." },
  { zh: "閏月，甲午，上幸南陽，召校官弟子作雅樂，奏《鹿鳴》，帝自御塤篪和之，以娛嘉賓。", literal: "In the intercalary month, on the day jiawu, the emperor visited Nanyang, summoned the disciples of the Director of Studies to perform elegant music, played \"Deer Cry,\" and the emperor himself played the xun and chi in harmony to entertain the honored guests.", idiomatic: "In the intercalary month, on jiawu day, the emperor visited Nanyang, summoned the Director of Studies' disciples to perform court music and play \"Deer Cry,\" and himself played the xun and chi in harmony to entertain the guests." },
  { zh: "還，幸南頓。", literal: "On the return he visited Nandun.", idiomatic: "On the return he visited Nandun." },
  { zh: "冬，十二月，甲午，還宮。", literal: "In winter, the twelfth month, on the day jiawu, he returned to the palace.", idiomatic: "In winter, in the twelfth month, on jiawu day, he returned to the palace." },
  { zh: "初，陵陽侯丁綝卒，子鴻當襲封，上書稱病，讓國於弟盛，不報。", literal: "Earlier, Marquis of Lingyang Ding Hong died; his son Hong was to inherit the enfeoffment, submitted a memorial claiming illness, and yielded the state to his younger brother Sheng—no reply.", idiomatic: "Earlier Marquis of Lingyang Ding Hong died. His son Hong was to inherit the title, submitted a memorial claiming illness, and yielded the state to his younger brother Sheng. No reply came." },
  { zh: "既葬，乃掛衰絰於塚廬而逃去。", literal: "After the burial he hung mourning hemp on the tomb hut and fled.", idiomatic: "After the burial he hung mourning dress on the tomb hut and fled." },
  { zh: "友人九江鮑駿遇鴻於東海，讓之曰；", literal: "His friend Bao Jun of Jiujiang met Hong on the eastern sea and reproved him, saying:", idiomatic: "His friend Bao Jun of Jiujiang met Hong on the eastern sea and reproved him:" },
  { zh: "「昔伯夷、吳札，亂世權行，故得申其志耳。", literal: "\"In antiquity Boyi and Wu Zha acted by expedient authority in chaotic times—therefore they could express their aims.", idiomatic: "\"In antiquity Boyi and Wu Zha acted by expedient authority in chaotic times and so could fulfill their aims." },
  { zh: "《春秋》之義，不以家事廢王事。", literal: "\"The meaning of the Spring and Autumn Annals is not to let family affairs abolish royal affairs.\"", idiomatic: "\"The Spring and Autumn Annals teach that family affairs must not abolish royal affairs.\"" },
  { zh: "今子以兄弟私恩而絕父不滅之基，可乎？", literal: "\"Now you, because of private affection between brothers, would cut off your father's undying foundation—can that be right?\"", idiomatic: "\"Now you would cut off your father's undying foundation for private brotherly affection. Can that be right?\"" },
  { zh: "」鴻感悟垂涕，乃還就國。", literal: "\" Hong was moved to understanding, shed tears, and thereupon returned to take up the state.", idiomatic: "\" Hong was moved to tears and returned to take up the state." },
  { zh: "鮑駿因上書薦鴻經學至行，上征鴻為侍中。", literal: "Bao Jun thereupon submitted a memorial recommending Hong's classical learning and utmost conduct; the emperor summoned Hong as Palace Attendant.", idiomatic: "Bao Jun then memorialized recommending Hong's classical learning and utmost conduct. The emperor summoned Hong as Palace Attendant." },
  { zh: "春，正月，東平王蒼與諸王俱來朝，月餘，還國。", literal: "In spring, the first month, the King of Dongping, Cang, together with the various kings all came to court; after more than a month they returned to their states.", idiomatic: "In spring, in the first month, the King of Dongping, Cang, came to court with the other kings. After more than a month they returned to their states." },
  { zh: "帝臨送歸宮，淒然懷思，乃遣使手詔賜東平國中傅曰：「辭別之後，獨坐不樂，因就車歸，伏軾而吟，瞻望永懷，實勞我心。", literal: "The emperor personally saw them off returning to the palace, desolate in longing thought, and thereupon sent an envoy with an imperial letter in his own hand to grant the Dongping state's Chancellor, saying: \"After we parted I sat alone without joy; I thereupon took the carriage back, leaned on the crossbar and chanted, gazed afar in lasting remembrance—it truly has wearied my heart.", idiomatic: "The emperor personally saw them off at the palace, desolate with longing, and sent an envoy with a letter in his own hand to the Dongping Chancellor: \"After we parted I sat alone without joy. I took my carriage back, leaned on the rail and chanted, and gazed afar in lasting remembrance—it has truly wearied my heart." },
  { zh: "誦及《采菽》，以增歎息。", literal: "When I recited \"Gathering Beans\" my sighs increased.\"", idiomatic: "Reciting \"Gathering Beans\" only increased my sighs.\"" },
  { zh: "日者問東平王：『處家何等最樂？", literal: "\"The other day I asked the King of Dongping: 'In dwelling at home what is most joyful?'", idiomatic: "\"The other day I asked the King of Dongping, 'What is most joyful in home life?'" },
  { zh: "』王言：『為善最樂。", literal: "'The king said: 'Doing good is most joyful.'", idiomatic: "'He said, 'Doing good is most joyful.'\"" },
  { zh: "』其言甚大，副是要腹矣。", literal: "'His words were very great—they match that belly of his.'", idiomatic: "'His words were grand indeed—they match that belly of his.'\"" },
  { zh: "今送列侯印十九枚，", literal: "\"Now I send nineteen marquis seals,", idiomatic: "\"Now I send nineteen marquis seals," },
  { zh: "諸王子年五歲已上能趨拜者，皆令帶之。", literal: "for all the kings' sons five years old and above who can hurry and bow—let them all wear them.\"", idiomatic: "for all the kings' sons five years old and above who can hurry and bow—let them all wear them.\"" },
  { zh: "春，哀牢王柳貌率其民五萬餘戶內附，以其地置哀牢、博南二縣。", literal: "In spring the king of Ailao, Liu Mao, led his people of more than fifty thousand households to submit within; on their territory he established the two counties Ailao and Bonan.", idiomatic: "In spring the king of Ailao, Liu Mao, led more than fifty thousand households to submit. Their territory was made the two counties Ailao and Bonan." },
  { zh: "始通博南山，度蘭倉水，行者苦之，", literal: "They first opened the Bonan Mountains, crossed the Lan Cang waters, and travelers found it bitter;", idiomatic: "They first opened the Bonan Mountains and crossed the Lan Cang waters, and travelers suffered;" },
  { zh: "歌曰：「漢德廣，開不賓；", literal: "they sang: \"Han virtue is broad, opening those who do not submit;", idiomatic: "they sang, \"Han virtue is broad, opening those who do not submit;" },
  { zh: "度蘭倉，為它人。", literal: "crossing Lan Cang—for others.'", idiomatic: "crossing Lan Cang—for others.'\"" },
  { zh: "初，平帝時，河、汴決壞，久而不修。", literal: "Earlier, in Emperor Ping's time, the Yellow River and Bian Canal burst and were ruined, long unrepaired.", idiomatic: "Earlier, in Emperor Ping's time, the Yellow River and Bian Canal burst and were ruined and long went unrepaired." },
  { zh: "建武十年，光武欲修之；", literal: "In the tenth year of Jianwu, Emperor Guangwu wished to repair them;", idiomatic: "In the tenth year of Jianwu, Emperor Guangwu wished to repair them;" },
  { zh: "浚儀令樂俊上言，民新被兵革，未宜興役，乃止。", literal: "the magistrate of Junyi, Yue Jun, submitted that the people had newly suffered arms and revolution and it was not fitting to raise corvée—thereupon it stopped.", idiomatic: "the magistrate of Junyi, Yue Jun, submitted that the people had newly suffered war and corvée was unfitting, and work stopped." },
  { zh: "其後汴渠東侵，日月彌廣，兗、豫百姓怨歎，以為縣官恆興佗役，不先民急，會有薦樂浪王景能治水者，夏，四月，詔發卒數十萬，遣景與將作謁者王吳修汴渠堤，自滎陽東至千乘海口千餘里，十里立一水門，令更相洄注，無復潰漏之患。", literal: "Afterward the Bian Canal invaded eastward, day by day growing wider; the people of Yan and Yu groaned in resentment, holding that the officials constantly raised other corvée and did not put the people's urgency first. It happened that someone recommended Wang Jing, king of Lelang, as able to control water; in summer, the fourth month, an edict mobilized several hundred thousand conscripts and sent Jing together with Master of Works Gentleman Wang Wu to repair the Bian Canal dikes—from east of Xingyang to the mouth at Qiansheng more than a thousand li, setting a water gate every ten li, ordering mutual back-flow irrigation, with no further fear of breach and seepage.", idiomatic: "Later the Bian Canal spread eastward day by day. The people of Yan and Yu groaned that officials constantly raised other corvée and ignored urgent needs. Someone recommended Wang Jing, king of Lelang, as able to control water. In summer, in the fourth month, an edict mobilized several hundred thousand laborers and sent Jing with Master of Works Gentleman Wang Wu to repair the Bian dikes from east of Xingyang to the Qiansheng estuary, more than a thousand li, with a sluice gate every ten li for mutual back-flow, ending breach and seepage." },
  { zh: "景雖簡省役費，然猶以百億計焉。", literal: "Though Jing simplified and reduced corvée costs, it still amounted to tens of billions.", idiomatic: "Though Jing reduced corvée costs, the expense still ran to tens of billions." },
  { zh: "秋，七月，乙亥，司空伏恭罷；", literal: "In autumn, the seventh month, on the day yihai, Minister of Works Fu Gong was dismissed;", idiomatic: "In autumn, in the seventh month, on yihai day, Minister of Works Fu Gong was dismissed;" },
  { zh: "乙未，以大司農牟融為司空。", literal: "on the day yiwei, Grand Minister of Agriculture Mou Rong was made Minister of Works.", idiomatic: "on yiwei day Grand Minister of Agriculture Mou Rong was made Minister of Works." },
  { zh: "是時，天下安平，人無徭役，歲比登稔，百姓殷富，粟斛三十，牛羊被野。", literal: "At this time the realm was peaceful and secure, men had no corvée, year after year the harvest ripened, the hundred surnames were prosperous and rich, grain was thirty per hu, cattle and sheep covered the wilds.", idiomatic: "At this time the realm was peaceful, men had no corvée, harvests succeeded year after year, the people were prosperous, grain sold at thirty cash per hu, and cattle and sheep covered the wilds." },
  { zh: "夏，四月，汴渠成；", literal: "In summer, the fourth month, the Bian Canal was completed;", idiomatic: "In summer, in the fourth month, the Bian Canal was completed;" },
  { zh: "河、汴分流，復其舊跡。", literal: "the Yellow River and Bian Canal divided their flows and returned to their old courses.", idiomatic: "the Yellow River and Bian Canal divided their flows and returned to their old courses." },
  { zh: "辛乙，帝行幸滎陽，巡行河渠，遂渡河，登太行，幸上黨；", literal: "On xinyi the emperor traveled to Xingyang, inspected the rivers and canals, then crossed the river, ascended Taihang, and visited Shangdang;", idiomatic: "On xinyi day the emperor traveled to Xingyang, inspected the rivers and canals, crossed the river, ascended Taihang, and visited Shangdang;" },
  { zh: "壬寅，還宮。", literal: "on the day renyin he returned to the palace.", idiomatic: "on renyin day he returned to the palace." },
  { zh: "冬，十月，壬辰晦，日有食之。", literal: "In winter, the tenth month, on the last day renchen of the month, there was a solar eclipse.", idiomatic: "In winter, in the tenth month, on the last day renchen of the month, there was a solar eclipse." },
  { zh: "楚王英與方士作金龜、玉鶴，刻文字為符瑞。", literal: "The King of Chu, Ying, with magicians made golden tortoises and jade cranes, carving characters as talismans of auspicious omen.", idiomatic: "The King of Chu, Ying, with magicians made golden tortoises and jade cranes and carved characters as auspicious talismans." },
  { zh: "男子燕廣告英與漁陽王平、顏忠等造作圖書，有逆謀；", literal: "A man named Yan Guang reported that Ying together with the King of Yuyang, Ping, Yan Zhong, and others forged charts and writings and had a treasonous plot;", idiomatic: "A man named Yan Guang reported that Ying together with the King of Yuyang, Ping, Yan Zhong, and others forged charts and writings in a treasonous plot;" },
  { zh: "事下案驗。", literal: "the matter was sent down for investigation and verification.", idiomatic: "the matter was sent down for investigation." },
  { zh: "有司奏「英大逆不道，請誅之。", literal: "The responsible officials memorialized: \"Ying has committed great treason and is not in the Way—we request execution.\"", idiomatic: "The responsible officials memorialized, \"Ying has committed great treason. We request execution.\"" },
  { zh: "」帝以親親不忍。", literal: "\" The emperor, because of kinship affection, could not bear it.", idiomatic: "\" The emperor, for kinship's sake, could not bear it." },
  { zh: "十一月，廢英，徙丹楊涇縣，賜湯沐邑五百戶；", literal: "In the eleventh month Ying was deposed, moved to Jing county in Danyang, and granted five hundred households for bath and maintenance;", idiomatic: "In the eleventh month Ying was deposed, moved to Jing county in Danyang, and granted five hundred bath-and-maintenance households;" },
  { zh: "男女為侯、主者，食邑如故；", literal: "sons and daughters who were marquises or ladies kept their food fiefs as before;", idiomatic: "sons and daughters who were marquises or ladies kept their fiefs as before;" },
  { zh: "許太后勿上璽綬，留住楚宮。", literal: "the Queen Dowager Xu was not to present seal and cord and was to remain in the Chu palace.", idiomatic: "Queen Dowager Xu was not to present seal and cord and was to remain in the Chu palace." },
  { zh: "先是有私以英謀告司徒虞延者，延以英籓戚至親，不然其言。", literal: "Earlier someone had privately reported Ying's plot to Minister of Education Yu Yan; Yan, because Ying was a close kinsman of the imperial house, did not credit the words.", idiomatic: "Earlier someone had privately reported Ying's plot to Minister of Education Yu Yan. Yan, because Ying was a close imperial kinsman, did not credit it." },
  { zh: "及英事覺，詔書切讓延。", literal: "When Ying's affair came to light, an edict sharply reproached Yan.", idiomatic: "When Ying's affair came to light, an edict sharply reproached Yan." },
  { zh: "春，三月，甲戌，延自殺。", literal: "In spring, the third month, on the day jiaxu, Yan killed himself.", idiomatic: "In spring, in the third month, on jiaxu day, Yan killed himself." },
  { zh: "以太常周澤行司徒事；", literal: "Grand Master of Ceremonies Zhou Ze acted as Minister of Education;", idiomatic: "Grand Master of Ceremonies Zhou Ze acted as Minister of Education;" },
  { zh: "頃之，復為太常。", literal: "before long he again became Grand Master of Ceremonies.", idiomatic: "before long he again became Grand Master of Ceremonies." },
  { zh: "夏，四月，丁巳，以巨鹿太守南陽邢穆為司徒。", literal: "In summer, the fourth month, on the day dingsi, the Administrator of Julu, Xing Mu of Nanyang, was made Minister of Education.", idiomatic: "In summer, in the fourth month, on dingsi day, the Administrator of Julu, Xing Mu of Nanyang, was made Minister of Education." },
  { zh: "楚王英至丹楊，自殺。", literal: "The King of Chu, Ying, reached Danyang and killed himself.", idiomatic: "The King of Chu, Ying, reached Danyang and killed himself." },
  { zh: "詔以諸侯禮葬於涇。", literal: "An edict ordered burial at Jing with the rites of a feudal lord.", idiomatic: "An edict ordered burial at Jing with feudal-lord rites." },
  { zh: "封燕廣為折奸侯。", literal: "Yan Guang was enfeoffed Marquis Who Breaks Treachery.", idiomatic: "Yan Guang was enfeoffed Marquis Who Breaks Treachery." },
  { zh: "是時，窮治楚獄，遂至累年。", literal: "At this time the Chu case was prosecuted to the limit and continued for successive years.", idiomatic: "At this time the Chu case was prosecuted to the limit and dragged on for years." },
  { zh: "其辭語相連，自京師親戚、諸侯、州郡豪桀及考案吏，阿附坐死、徙者以千數，而繫獄者尚數千人。", literal: "Their words implicated one another in succession—from capital kinsmen, feudal lords, commandery and district powerful men, and investigating clerks; those who died or were banished for complicity numbered in the thousands, while those still bound in prison were several thousand more.", idiomatic: "Their testimony implicated one another—from capital kinsmen, feudal lords, commandery and district powerful men, and investigating clerks. Those who died or were banished for complicity numbered in the thousands, and several thousand more remained in prison." },
  { zh: "初，樊鯈弟鮪為其子賞求楚王英女，鯈聞而止之曰：「建武中，吾家並受榮寵，一宗五侯。", literal: "Earlier Fan Chuo's younger brother Wei sought the daughter of the King of Chu, Ying, for his son Shang; Chuo heard of it and stopped him, saying: \"In the Jianwu period our family together received glory and favor—one clan, five marquises.", idiomatic: "Earlier Fan Chuo's younger brother Wei sought the King of Chu Ying's daughter for his son Shang. Chuo heard of it and stopped him: \"In the Jianwu period our family together received glory—one clan, five marquises." },
  { zh: "時特進一言，女可以配王，男可以尚主；", literal: "At that time one word from a Special Advancement— a daughter could marry a king, a son could marry an imperial princess;", idiomatic: "At that time one word from a Special Advancement—a daughter could marry a king, a son an imperial princess;" },
  { zh: "但以貴寵過盛，即為禍患，故不為也，且爾一子，奈何棄之於楚乎！", literal: "but because honor and favor were too excessive, it at once became disaster—therefore we did not do it. And you have but one son—how can you cast him off on Chu!\"", idiomatic: "but because excessive honor and favor at once become disaster, we did not. And you have but one son—how can you cast him off on Chu!\"" },
  { zh: "」鮪不從。", literal: "\" Wei did not follow this.", idiomatic: "\" Wei did not listen." },
  { zh: "及楚事覺，鯈已卒，上追念鯈謹恪，故其諸子皆得不坐。", literal: "When the Chu affair came to light Chuo had already died; the emperor recalled Chuo's careful reverence, and therefore his various sons all escaped punishment.", idiomatic: "When the Chu affair came to light Chuo had already died. The emperor recalled Chuo's careful loyalty, and therefore his sons all escaped punishment." },
  { zh: "英陰疏天下名士，上得其錄，有吳郡太守尹興名，乃征興及掾史五百餘人詣廷尉就考。", literal: "Ying had secretly listed famous men of the realm; the emperor obtained the register, and there was the name of the Administrator of Wu commandery, Yin Xing; he thereupon summoned Xing and more than five hundred clerks and assistants to the Court Commandant for examination.", idiomatic: "Ying had secretly listed famous men of the realm. The emperor obtained the register and found the Administrator of Wu, Yin Xing. He summoned Xing and more than five hundred clerks and assistants to the Court Commandant for examination." },
  { zh: "諸吏不勝掠治，死者太半；", literal: "The various clerks could not bear the torment of interrogation; more than half died;", idiomatic: "The clerks could not bear the torment of interrogation. More than half died;" },
  { zh: "惟門下掾陸續、主簿梁宏、功曹史駟勳，備受五毒，肌肉消爛，終無異辭。", literal: "Only the Gatehouse Clerk Lu Xu, Registrar Liang Hong, and Merit Officer Clerk Si Xun fully suffered the five poisons; their flesh wasted and rotted away, yet in the end they made no differing statements.", idiomatic: "Only Gatehouse Clerk Lu Xu, Registrar Liang Hong, and Merit Officer Clerk Si Xun endured the full five poisons; their flesh wasted away, yet they never changed their testimony." },
  { zh: "續母自吳來雒陽，作食以饋續。", literal: "Xu's mother came from Wu to Luoyang and prepared food to feed Xu.", idiomatic: "Xu's mother came from Wu to Luoyang and prepared food to bring to him." },
  { zh: "續雖見考，辭色未嘗變，而對食悲泣不自勝。", literal: "Though Xu was under examination, his expression never changed; yet facing the food he wept in grief beyond control.", idiomatic: "Though Xu was under torture, his composure never changed; yet when he saw the food he wept uncontrollably." },
  { zh: "治獄使者問其故，續曰：「母來不得見，故悲耳。", literal: "The prison investigator asked the reason; Xu said: \"My mother came and I could not see her—therefore I grieve.\"", idiomatic: "The prison investigator asked why; Xu said, \"My mother came and I could not see her—that is why I grieve.\"" },
  { zh: "」問：「何以知之？", literal: "\" He was asked: \"How do you know?\"", idiomatic: "\" He was asked, \"How do you know?\"" },
  { zh: "」續曰：「母截肉未嘗不方，斷蔥以寸為度，故知之。", literal: "\" Xu said: \"When my mother cuts meat it is never not square; she cuts scallions by the inch as measure—therefore I know.\"", idiomatic: "\" Xu said, \"Mother never cuts meat except in perfect squares and measures scallions by the inch—that is how I know.\"" },
  { zh: "」使者以狀聞，上乃赦興等，禁錮終身。", literal: "\" The investigator reported the circumstance; the emperor thereupon pardoned Xing and the others and confined them for life.", idiomatic: "\" The investigator reported this; the emperor then pardoned Xing and the others from death but confined them for life." },
  { zh: "顏忠、王平辭引隧鄉侯耿建、朗陵侯臧信、濩澤侯鄧鯉、曲成侯劉建。", literal: "Yan Zhong and Wang Ping in their statements implicated Marquis of Suixiang Geng Jian, Marquis of Langling Zang Xin, Marquis of Huoze Deng Li, and Marquis of Qucheng Liu Jian.", idiomatic: "Yan Zhong and Wang Ping in their confessions implicated Marquis of Suixiang Geng Jian, Marquis of Langling Zang Xin, Marquis of Huoze Deng Li, and Marquis of Qucheng Liu Jian." },
  { zh: "建等辭未嘗與忠、平相見。", literal: "Jian and the others in their statements said they had never met Zhong or Ping.", idiomatic: "Jian and the others said in their statements that they had never even met Zhong or Ping." },
  { zh: "是時，上怒甚，吏皆惶恐，諸所連及，率一切陷入，無敢以情恕者。", literal: "At this time the emperor's anger was very great; the officials were all fearful; all who were implicated were generally dragged in together, and none dared spare anyone out of sympathy.", idiomatic: "The emperor was furious; officials were terrified; everyone implicated was generally swept in together, and none dared spare anyone out of sympathy." },
  { zh: "侍御史寋朗心傷其冤，試以建等物色，獨問忠、平，而二人錯愕不能對。", literal: "Attendant Censor Jian Lang, pained at their wrongful suffering, tried describing Jian and the others' appearance and questioned only Zhong and Ping alone—and the two were flustered and could not answer.", idiomatic: "Attendant Censor Jian Lang, pained at the injustice, described Jian and the others' appearance and questioned only Zhong and Ping—and the two were flustered and could not answer." },
  { zh: "朗知其詐，乃上言：「建等無奸，專為忠、平所誣；", literal: "Lang knew it was fraud and thereupon submitted: \"Jian and the others have no treachery—they are solely slandered by Zhong and Ping;\"", idiomatic: "Lang knew it was a fraud and memorialized, \"Jian and the others are innocent and were solely slandered by Zhong and Ping;\"" },
  { zh: "疑天下無辜，類多如此。", literal: "\"I suspect innocents under heaven mostly follow this pattern.\"", idiomatic: "\"I suspect many innocents under heaven suffer the same.\"" },
  { zh: "」帝曰：「即如是，忠、平何故引之？", literal: "\" The emperor said: \"If so, why did Zhong and Ping implicate them?\"", idiomatic: "\" The emperor said, \"If so, why did Zhong and Ping implicate them?\"" },
  { zh: "」對曰：「忠、平自知所犯不道，故多有虛引，冀以自明。", literal: "\" He replied: \"Zhong and Ping knew themselves guilty of impiety; therefore they made many false imputations, hoping thereby to clear themselves.\"", idiomatic: "\" He replied, \"Zhong and Ping knew their own crimes were capital; they made many false imputations hoping to clear themselves.\"" },
  { zh: "」帝曰：「即如是，何不早奏？", literal: "\" The emperor said: \"If so, why not memorialize earlier?\"", idiomatic: "\" The emperor said, \"If so, why did you not report it earlier?\"" },
  { zh: "」對曰：「臣恐海內別有發其奸者。", literal: "\" He replied: \"Your servant feared that elsewhere within the seas someone else would expose their treachery.\"", idiomatic: "\" He replied, \"Your servant feared someone else in the empire would expose their treachery.\"" },
  { zh: "」帝怒曰：「吏持兩端！", literal: "\" The emperor angrily said: \"The official holds both ends!\"", idiomatic: "\" The emperor said angrily, \"The official is playing both sides!\"" },
  { zh: "」促提下捶之。", literal: "\" He hurriedly ordered him seized and beaten down below.", idiomatic: "\" He ordered him seized and beaten at once." },
  { zh: "左右方引去，朗曰：「願一言而死。", literal: "The attendants were just leading him away when Lang said: \"I wish one word before I die.\"", idiomatic: "As attendants were leading him away, Lang said, \"I beg one word before I die.\"" },
  { zh: "」帝曰：「誰與共為章？", literal: "\" The emperor said: \"Who joined you in drafting the memorial?\"", idiomatic: "\" The emperor said, \"Who drafted the memorial with you?\"" },
  { zh: "」對曰：「臣獨作之。", literal: "\" He replied: \"Your servant composed it alone.\"", idiomatic: "\" He replied, \"Your servant wrote it alone.\"" },
  { zh: "」上曰：「何以不與三府議？", literal: "\" The emperor said: \"Why did you not deliberate with the Three Excellencies?\"", idiomatic: "\" The emperor said, \"Why did you not consult the Three Excellencies?\"" },
  { zh: "」對曰：「臣自知當必族滅，不敢多污染人。", literal: "\" He replied: \"Your servant knew he must certainly suffer clan extermination and dared not broadly defile others.\"", idiomatic: "\" He replied, \"Your servant knew he must suffer clan extermination and dared not involve others.\"" },
  { zh: "」上曰：「何故族滅？", literal: "\" The emperor said: \"Why clan extermination?\"", idiomatic: "\" The emperor said, \"Why clan extermination?\"" },
  { zh: "」對曰：「臣考事一年，不能窮盡奸狀，反為罪人訟冤，故知當族滅，然臣所以言者，誠冀陛下一覺悟而已。", literal: "\" He replied: \"Your servant investigated cases for a year, could not exhaust treacherous circumstances, and instead pleaded the criminals' wrongs—therefore he knows he should suffer clan extermination; yet what your servant speaks is truly only hoping Your Majesty will awaken.\"", idiomatic: "\" He replied, \"Your servant investigated cases for a year, could not exhaust every treachery, and instead pleaded criminals' innocence—therefore he knows he deserves clan extermination; yet he speaks only hoping Your Majesty will awaken.\"" },
  { zh: "臣見考囚在事者，鹹共言妖惡大故，臣子所宜同疾，今出之不如入之，可無後責。", literal: "\"Your servant sees those examining prisoners on duty all alike say great evil of sorcery is what subjects should jointly hate; now releasing them is not as good as keeping them in—one can avoid later blame.\"", idiomatic: "\"Your servant sees examiners on duty all say great sorcery is what subjects should hate together; releasing prisoners is worse than keeping them in, to avoid later blame.\"" },
  { zh: "是以考一連十，考十連百。", literal: "\"Therefore examining one implicates ten; examining ten implicates a hundred.\"", idiomatic: "\"Therefore one examination implicates ten, and ten implicate a hundred.\"" },
  { zh: "又公卿朝會，陛下問以得失，皆長跪言：『舊制，大罪禍及九族；", literal: "\"Moreover at court assemblies of duke-and-ministers, when Your Majesty asks about right and wrong, all kneel long and say: 'By old regulation, great crimes bring disaster to nine clans;'", idiomatic: "\"Moreover at court assemblies, when Your Majesty asks their judgment, all kneel and say, 'By old regulation great crimes brought disaster to nine clans;'\"" },
  { zh: "陛下大恩，裁止於身，天下幸甚！", literal: "\"Your Majesty's great grace cuts it off at the person alone—the realm is greatly fortunate!'", idiomatic: "'Your Majesty's great grace limits punishment to the person alone—the realm is greatly fortunate!'\"" },
  { zh: "』及其歸捨，口雖不言而仰屋竊歎，莫不知其多冤，無敢悟陛下言者。", literal: "\"Yet when they return home, though their mouths do not speak they sigh secretly looking up at the roof beams—none do not know how many are wronged, yet none dares enlighten Your Majesty in speech.\"", idiomatic: "'Yet at home, though they say nothing, they sigh secretly at the rafters—everyone knows how many are wronged, yet none dares tell Your Majesty plainly.'\"" },
  { zh: "臣今所陳，誠死無悔！", literal: "\"What your servant now presents—truly he dies without regret!\"", idiomatic: "\"What your servant now presents, he offers without regret even unto death!\"" },
  { zh: "」帝意解，詔遣朗出。", literal: "\" The emperor's mind eased; an edict sent Lang out.", idiomatic: "\" The emperor's anger eased, and an edict sent Lang out." },
  { zh: "後二日，車駕自幸洛陽獄錄囚徒，理出千餘人。", literal: "Two days later the imperial carriage personally favored the Luoyang prison to review prisoners and released more than a thousand.", idiomatic: "Two days later the emperor personally visited the Luoyang prison, reviewed the prisoners, and released more than a thousand." },
  { zh: "時天旱，即大雨。", literal: "At the time the sky was drought-stricken; immediately great rain fell.", idiomatic: "The land was in drought; rain fell at once." },
  { zh: "馬後亦以楚獄多濫，乘間為帝言之，帝惻然感悟，夜起彷徨，由是多所降宥。", literal: "Empress Ma also, because the Chu prison cases were much excessive, seized an interval to speak to the emperor; the emperor was moved to pity and awakened, rose at night and paced about, and thereby many received reduction and pardon.", idiomatic: "Empress Ma also said the Chu cases were excessive; the emperor was moved, rose at night and paced in distress, and thereafter granted many reductions and pardons." },
  { zh: "任城令汝南袁安遷楚郡太守，到郡不入府，先往案楚王英獄事，理其無明驗者，條上出之。", literal: "Magistrate of Rencheng Yuan An of Runan was transferred to Administrator of Chu; arriving at the commandery he did not enter the headquarters but first went to examine Prince Ying of Chu's prison cases, sorted out those without clear evidence, and listed them upward for release.", idiomatic: "Magistrate of Rencheng Yuan An of Runan was transferred to Administrator of Chu. On arrival he did not enter headquarters but first examined Prince Ying of Chu's cases, sorted out those without clear evidence, and memorialized for their release." },
  { zh: "府丞、掾史皆叩頭爭，以為「阿附反虜，法與同罪，不可。", literal: "The headquarters assistants and clerks all knocked their heads and contended, holding that \"to favor and attach to the rebel barbarian is law with the same crime—it cannot be done.\"", idiomatic: "The headquarters assistants and clerks all prostrated themselves in protest, saying, \"To favor the rebel is the same crime by law—it cannot be done.\"" },
  { zh: "」安曰：「如有不合，太守自當坐之，不以相及也。", literal: "\" An said: \"If there is what does not fit, the Administrator himself should bear punishment—it will not extend to you.\"", idiomatic: "\" An said, \"If I am wrong, the Administrator alone will bear punishment—it will not extend to you.\"" },
  { zh: "遂分別具奏。", literal: "Thereupon he separately prepared full memorials.", idiomatic: "Thereupon he submitted separate memorials in full." },
  { zh: "帝感悟，即報許，得出者四百餘家。", literal: "The emperor was moved and awakened, immediately replied permitting it, and those who could leave were more than four hundred households.", idiomatic: "The emperor was moved and at once approved; more than four hundred households were released." },
  { zh: "夏，五月，封故廣陵王荊子元壽為廣陵侯，食六縣。", literal: "In summer, the fifth month, the former King of Guangling Jing's son Yuan Shou was enfeoffed Marquis of Guangling with revenue from six counties.", idiomatic: "In summer, in the fifth month, the former King of Guangling Jing's son Yuan Shou was enfeoffed as Marquis of Guangling with revenue from six counties." },
  { zh: "又封竇融孫嘉為安豐侯。", literal: "Also Dou Rong's grandson Jia was enfeoffed Marquis of Anfeng.", idiomatic: "Dou Rong's grandson Jia was also enfeoffed as Marquis of Anfeng." },
  { zh: "初作壽陵，制：「令流水而已，無得起墳。", literal: "Construction of Shouling was first begun; regulations: \"Only allow flowing water; do not raise tomb mounds.\"", idiomatic: "Work began on Shouling with regulations: \"Only a flowing stream—no raised tomb mounds.\"" },
  { zh: "萬年之後，掃地而祭，杅水脯糒而已。", literal: "\"After ten thousand years, sweep the ground and sacrifice—only ladle-water, dried meat, and parched grain.\"", idiomatic: "\"After death, sweep the ground and sacrifice—only water, dried meat, and parched grain.\"" },
  { zh: "過百日，唯四時設奠。", literal: "\"Past a hundred days, only at the four seasons set offerings.\"", idiomatic: "\"After a hundred days, offerings only at the four seasons.\"" },
  { zh: "置吏卒數人，供給灑掃。", literal: "\"Place several clerk-soldiers to supply sprinkling and sweeping.\"", idiomatic: "\"Station a few clerks and soldiers for sprinkling and sweeping.\"" },
  { zh: "敢有所興作者。", literal: "\"Whoever dares any construction.\"", idiomatic: "\"Whoever dares any further construction\"" },
  { zh: "以擅議宗廟法從事。", literal: "\"—prosecute by the law on unauthorized discussion of the ancestral temple.\"", idiomatic: "\"—shall be prosecuted under the law on unauthorized discussion of the ancestral temple.\"" },
  { zh: "春，二月，庚子，上東巡。", literal: "In spring, the second month, on the day gengzi, the emperor toured east.", idiomatic: "In spring, in the second month, on gengzi day, the emperor toured east." },
  { zh: "癸亥，耕於下邳。", literal: "On the day guihai, he plowed at Xiapi.", idiomatic: "On guihai day he performed the plowing rite at Xiapi." },
  { zh: "三月，至魯，幸孔子宅，親御講堂，命皇太子、諸王說《經》；", literal: "In the third month he reached Lu, favored Confucius's residence, personally attended the lecture hall, and ordered the crown prince and the various kings to expound the Classics;", idiomatic: "In the third month he reached Lu, visited Confucius's residence, personally attended the lecture hall, and ordered the crown prince and the kings to expound the Classics;" },
  { zh: "又幸東平、大梁。", literal: "He also favored Dongping and Daliang.", idiomatic: "He also visited Dongping and Daliang." },
  { zh: "夏，四月，庚子，還宮。", literal: "In summer, the fourth month, on the day gengzi, he returned to the palace.", idiomatic: "In summer, in the fourth month, on gengzi day, he returned to the palace." },
  { zh: "封皇子恭為巨鹿王，黨為樂成王，衍為下邳王，暢為汝南王，昺為常山王，長為濟陰王；", literal: "The emperor's sons were enfeoffed: Gong as King of Julu, Dang as King of Lecheng, Yan as King of Xiapi, Chang as King of Runan, Bing as King of Changshan, and Chang as King of Jiyin;", idiomatic: "The emperor's sons were enfeoffed: Gong as King of Julu, Dang as King of Lecheng, Yan as King of Xiapi, Chang as King of Runan, Bing as King of Changshan, and Chang as King of Jiyin;" },
  { zh: "帝親定其封域，裁令半楚、淮陽。", literal: "the emperor personally fixed their enfeoffment territories, cutting them to half of Chu and Huaiyang.", idiomatic: "the emperor personally fixed their domains, limiting them to half the size of Chu and Huaiyang." },
  { zh: "馬後曰：「諸子數縣，於制不已儉乎？", literal: "Empress Ma said: \"The sons have several counties—is this not already too lavish by regulation?\"", idiomatic: "Empress Ma said, \"The sons hold several counties—is that not already too lavish by regulation?\"" },
  { zh: "」帝曰：「我子豈宜與先帝子等，歲給二千萬足矣！", literal: "\" The emperor said: \"How should my sons be equal to the former emperor's sons—two tens of millions per year is enough!\"", idiomatic: "\" The emperor said, \"How should my sons rank with the former emperor's sons—twenty million a year is enough!\"" },
  { zh: "乙巳，赦天下。", literal: "On the day yisi, he pardoned all under heaven.", idiomatic: "On yisi day he proclaimed a general amnesty." },
  { zh: "謁者僕射耿秉數上言請擊匈奴，上以顯親侯竇固嘗從其世父融在河西，明習邊事，乃使秉、固與太僕祭肜、虎賁中郎將馬廖、下博侯劉張、好畤侯耿忠等共議之。", literal: "Gentleman-in-Attendance Commandant Geng Bing several times submitted requesting attack on the Xiongnu; the emperor because Illustrious Kin Marquis Dou Gu had once followed his father's elder brother Rong in Hexi and clearly knew border affairs, therefore had Bing, Gu, Grand Master of the Stud Ji Tong, Tiger-Gallant Center Commandant Ma Liao, Marquis of Xiabo Liu Zhang, Marquis of Haozhi Geng Zhong, and others jointly deliberate it.", idiomatic: "Gentleman-in-Attendance Commandant Geng Bing repeatedly memorialized to attack the Xiongnu. Because Illustrious Kin Marquis Dou Gu had followed his uncle Rong in Hexi and knew border affairs well, the emperor had Bing, Gu, Grand Master of the Stud Ji Tong, Tiger-Gallant Center Commandant Ma Liao, Marquis of Xiabo Liu Zhang, Marquis of Haozhi Geng Zhong, and others deliberate the campaign together." },
  { zh: "耿秉曰：「昔者匈奴援引弓之類，並左衽之屬，故不可得而制。", literal: "Geng Bing said: \"Formerly the Xiongnu drew on bow-bearing kinds and all left-lapel peoples together—therefore they could not be controlled.\"", idiomatic: "Geng Bing said, \"Formerly the Xiongnu drew on bow-bearing peoples and all who wore the left lapel together, and could not be controlled.\"" },
  { zh: "孝武既得河西四郡及居延、朔方，虜失其肥饒畜兵之地，羌、胡分離；", literal: "\"Emperor Wu having obtained the four Hexi commanderies and Juyan and Shuofang, the barbarians lost their fat, rich lands for raising troops; Qiang and Hu were separated;\"", idiomatic: "\"After Emperor Wu took the four Hexi commanderies plus Juyan and Shuofang, the barbarians lost their rich lands for raising troops, and the Qiang and Hu were separated;\"" },
  { zh: "唯有西域，俄復內屬；", literal: "\"only the Western Region, shortly again submitted within;\"", idiomatic: "\"only the Western Region soon submitted again;\"" },
  { zh: "故呼韓邪單于請事款塞，其勢易乘也。", literal: "\"therefore Chanyu Huhanxie requested service and knocked at the passes—their momentum was easy to ride.\"", idiomatic: "\"therefore Chanyu Huhanxie sought allegiance at the passes, and their momentum was easy to exploit.\"" },
  { zh: "今有南單于，形勢相似；", literal: "\"Now there is the Southern Chanyu—the situation is similar;\"", idiomatic: "\"Now there is the Southern Chanyu—the situation is similar;\"" },
  { zh: "然西域尚未內屬，北虜未有釁作。", literal: "\"yet the Western Region has not yet submitted within, and the Northern barbarians have not yet made a breach.\"", idiomatic: "\"yet the Western Region has not yet submitted, and the Northern barbarians have not yet given cause for war.\"" },
  { zh: "臣愚以為當先擊白山，得伊吾，破車師，通使烏孫諸國以斷其右臂；", literal: "\"Your servant foolishly holds that one should first strike White Mountain, obtain Yiwu, break Cheshi, and send envoys through the Wusun states to cut off their right arm;\"", idiomatic: "\"Your servant holds that we should first strike White Mountain, take Yiwu, break Cheshi, and open relations with the Wusun states to cut off their right arm;\"" },
  { zh: "伊吾亦有匈奴南呼衍一部。", literal: "\"At Yiwu there is also one division of the Xiongnu's southern Huyan.\"", idiomatic: "\"At Yiwu there is also a division of the Xiongnu's southern Huyan.\"" },
  { zh: "破此，復為折其左角，然後匈奴可擊也。", literal: "\"Breaking this, again one breaks their left horn—then the Xiongnu can be struck.\"", idiomatic: "\"Break that, and we break their left horn as well—then the Xiongnu can be struck.\"" },
  { zh: "」上善其言。", literal: "\" The emperor approved his words.", idiomatic: "\" The emperor approved his plan." },
  { zh: "議者或以為「今兵出白山，匈奴必並兵相助，又當分其東以離其眾。", literal: "Some in the deliberation held that \"if troops now go out to White Mountain, the Xiongnu will surely combine forces to assist; one should also divide their east to separate their masses.\"", idiomatic: "Some argued, \"If troops go to White Mountain, the Xiongnu will combine to help; we should also divide their eastern forces to split their host.\"" },
  { zh: "」上從之。", literal: "\" The emperor followed this.", idiomatic: "\" The emperor agreed." },
  { zh: "十二月，以秉為駙馬都尉，固為奉車都尉；", literal: "In the twelfth month, Bing was made Commandant of the Escort Horse and Gu made Commandant of the Imperial Carriage;", idiomatic: "In the twelfth month, Bing was made Commandant of the Escort Horse and Gu Commandant of the Imperial Carriage;" },
  { zh: "以騎都尉秦彭為秉副，耿忠為固副，皆置從事、司馬，出屯涼州。", literal: "Cavalry Commandant Qin Peng was made Bing's deputy and Geng Zhong Gu's deputy; all were given Attendants and Majors and went out to garrison at Liangzhou.", idiomatic: "Cavalry Commandant Qin Peng was made Bing's deputy and Geng Zhong Gu's deputy; each was given attendants and majors, and they encamped in Liangzhou." },
  { zh: "秉，國之子；", literal: "Bing was Guo's son;", idiomatic: "Bing was Guo's son;" },
  { zh: "忠，弇之子；", literal: "Zhong was Yan's son;", idiomatic: "Zhong was Yan's son;" },
  { zh: "廖，援之子也。", literal: "Liao was Yuan's son.", idiomatic: "Liao was Yuan's son." },
  { zh: "春，二月，遣肜與度遼將軍吳棠將河東、西河羌、胡及南單于兵萬一千騎出高闕塞，竇固、耿忠率酒泉、敦煌、張掖甲卒及盧水羌、胡萬二千騎出酒泉塞，耿秉、秦彭率武威、隴西、天水募士及羌、胡萬騎出張掖居延塞，騎都尉來苗、護烏桓校尉文穆將太原、雁門、代郡、上谷、漁陽、右北平、定襄郡兵及烏桓、鮮卑萬一千騎出平城塞，伐北匈奴。", literal: "In spring, the second month, Tong was sent with Crossing-the-Liao General Wu Tang to lead Hedong, Xihe, Qiang, Hu, and Southern Chanyu troops—eleven thousand cavalry—out Gaoque Pass; Dou Gu and Geng Zhong led Jiuquan, Dunhuang, and Zhangye armored soldiers plus Lushui Qiang and Hu—twelve thousand cavalry—out Jiuquan Pass; Geng Bing and Qin Peng led Wuwu, Longxi, and Tianshui recruited men plus Qiang and Hu—ten thousand cavalry—out Zhangye Juyan Pass; Cavalry Commandant Lai Miao and Protector of the Wuhuan Commandant Wen Mu led Taiyuan, Yanmen, Dai, Shanggu, Yuyang, Right Beiping, and Dingxiang commandery troops plus Wuhuan and Xianbei—eleven thousand cavalry—out Pingcheng Pass, to attack the Northern Xiongnu.", idiomatic: "In spring, in the second month, Tong was sent with Crossing-the-Liao General Wu Tang leading eleven thousand cavalry of Hedong, Xihe, Qiang, Hu, and the Southern Chanyu out Gaoque Pass; Dou Gu and Geng Zhong led twelve thousand armored men of Jiuquan, Dunhuang, and Zhangye plus Lushui Qiang and Hu out Jiuquan Pass; Geng Bing and Qin Peng led ten thousand recruits of Wuwei, Longxi, and Tianshui plus Qiang and Hu out Zhangye Juyan Pass; Cavalry Commandant Lai Miao and Protector of the Wuhuan Commandant Wen Mu led eleven thousand troops of Taiyuan, Yanmen, Dai, Shanggu, Yuyang, Right Beiping, and Dingxiang plus Wuhuan and Xianbei out Pingcheng Pass—to attack the Northern Xiongnu." },
  { zh: "竇固、耿忠至天山，擊呼衍王，斬首千餘級；", literal: "Dou Gu and Geng Zhong reached the Heavenly Mountains, struck the Huyan King, and beheaded more than a thousand;", idiomatic: "Dou Gu and Geng Zhong reached the Heavenly Mountains, struck the Huyan King, and took more than a thousand heads;" },
  { zh: "追至蒲類海，取伊吾盧地，置宜禾都尉，留吏士屯田伊吾盧城。", literal: "pursued to Pulei Sea, took Yiwulu territory, established the Chief Commandant of Yihe, and left clerks and soldiers to garrison-farm at Yiwulu city.", idiomatic: "pursued to Pulei Sea, took Yiwulu, established the Chief Commandant of Yihe, and left officials and soldiers to garrison-farm at Yiwulu." },
  { zh: "耿秉、秦彭擊匈林王，絕幕六百餘里，至三木樓山而還。", literal: "Geng Bing and Qin Peng struck the Hunlin King, crossed the desert more than six hundred li, reached Sanmulou Mountain, and returned.", idiomatic: "Geng Bing and Qin Peng struck the Hunlin King, crossed the desert more than six hundred li to Sanmulou Mountain, and returned." },
  { zh: "來苗、文穆至匈河水上，虜皆奔走，無所獲。", literal: "Lai Miao and Wen Mu reached the Xiongnu River's waters; the barbarians all fled—nothing was taken.", idiomatic: "Lai Miao and Wen Mu reached the Xiongnu River; the enemy fled and they took nothing." },
  { zh: "祭肜與南匈奴左賢王信不相得，出高闕塞九百餘里，得小山，信妄言以為涿邪山，不見虜而還。", literal: "Ji Tong and the Southern Xiongnu Left Worthy King Xin did not get along; going out Gaoque Pass more than nine hundred li they found a small hill; Xin falsely said it was Zhuoye Mountain, saw no barbarians, and returned.", idiomatic: "Ji Tong and the Southern Xiongnu Left Worthy King Xin quarreled; nine hundred li beyond Gaoque Pass they found a small hill; Xin falsely called it Zhuoye Mountain, saw no enemy, and returned." },
  { zh: "肜與吳棠坐逗留畏懦，下獄，免。", literal: "Tong and Wu Tang were charged with delay and cowardice, imprisoned, and dismissed.", idiomatic: "Tong and Wu Tang were charged with delay and cowardice, imprisoned, and dismissed from office." },
  { zh: "肜自恨無功，出獄數日，歐血死。", literal: "Tong himself resented having no achievement; several days after leaving prison he vomited blood and died.", idiomatic: "Tong, bitter at achieving nothing, vomited blood and died a few days after release." },
  { zh: "臨終，謂其子曰：「吾蒙國厚恩，奉使不稱，身死誠慚恨，義不可以無功受賞。", literal: "At the end he told his son: \"I received the state's thick grace; the mission did not fulfill its name—to die is truly shame and regret; righteousness cannot accept reward without achievement.\"", idiomatic: "On his deathbed he told his son, \"I received the state's great grace; the mission failed me—I die in shame; by right one must not take reward without merit.\"" },
  { zh: "死後，若悉簿上所得物，身自詣兵屯，效死前行，以副吾心。", literal: "\"After death, if you fully register on the books all goods received, go in person to the military garrison, and offer death advancing forward—to match my heart.\"", idiomatic: "\"After my death, register every gift you received, go yourself to the army, and die advancing—that will satisfy my heart.\"" },
  { zh: "」既卒，其子逢上疏，具陳遺言。", literal: "\" When he had died, his son Feng submitted a memorial fully stating the last words.", idiomatic: "\" When he died, his son Feng submitted a memorial setting out these last words." },
  { zh: "帝雅重肜，方更任用，聞之，大驚，嗟歎良久。", literal: "The emperor had greatly esteemed Tong and was just about to employ him again; on hearing this he was greatly startled and sighed long.", idiomatic: "The emperor had greatly esteemed Tong and was about to employ him again; on hearing this he was deeply shaken and sighed long." },
  { zh: "烏桓、鮮卑每朝賀京師，常過肜塚拜謁，仰天號泣。", literal: "Whenever the Wuhuan and Xianbei came to court audience at the capital they would pass Tong's tomb to bow and visit, looking up to heaven and wailing.", idiomatic: "Whenever the Wuhuan and Xianbei came to court they passed Tong's tomb to bow and wailed to heaven." },
  { zh: "遼東吏民為立祠，四時奉祭焉。", literal: "Officials and people of Liaodong built a shrine for him and offered sacrifice at the four seasons.", idiomatic: "Officials and people of Liaodong built him a shrine and sacrificed at the four seasons." },
  { zh: "竇固獨有功，加位特進。", literal: "Dou Gu alone had achievement; his rank was raised to Special Advance.", idiomatic: "Dou Gu alone had merit; his rank was raised to Special Advance." },
  { zh: "固使假司馬班超與從事郭恂俱使西域。", literal: "Gu sent Acting Major Ban Chao and Attendant Guo Xun together as envoys to the Western Region.", idiomatic: "Gu sent Acting Major Ban Chao and Attendant Guo Xun as envoys to the Western Region." },
  { zh: "超行到鄯善，鄯善王廣奉超禮敬甚備，後忽更疏懈。", literal: "Chao traveled to Shanshan; King Guang of Shanshan received Chao with very full ritual courtesy, then suddenly became more negligent and slack.", idiomatic: "Chao reached Shanshan; King Guang received him with full courtesy, then suddenly grew negligent." },
  { zh: "超謂其官屬曰：「寧覺廣禮意薄乎？", literal: "Chao said to his officials: \"Do you not notice Guang's ritual intent has grown thin?\"", idiomatic: "Chao said to his staff, \"Do you not notice Guang's courtesy has grown thin?\"" },
  { zh: "」官屬曰：「胡人不能常久，無它故也。", literal: "\" The officials said: \"Barbarians cannot be constant long—no other cause.\"", idiomatic: "\" His staff said, \"Barbarians cannot be constant long—there is no other cause.\"" },
  { zh: "」超曰：「此必有北虜使來，狐疑未知所從故也。", literal: "\" Chao said: \"This surely means a Northern barbarian envoy came—they are hesitant and do not know whom to follow.\"", idiomatic: "\" Chao said, \"A Northern barbarian envoy must have come—they are hesitating whom to follow.\"" },
  { zh: "明者睹未萌，況已著邪！", literal: "\"The clear-sighted see before sprouts appear—how much more when it is already evident!\"", idiomatic: "\"The clear-sighted see trouble before it sprouts—how much more when it is already plain!\"" },
  { zh: "」乃召侍胡，詐之曰：「匈奴使來數日，今安在乎？", literal: "\" He thereupon summoned the attending Hu and deceived them, saying: \"The Xiongnu envoy came several days ago—where is he now?\"", idiomatic: "\" He summoned the attending Hu and tricked them, saying, \"The Xiongnu envoy came several days ago—where is he now?\"" },
  { zh: "」侍胡惶恐曰：「到已三日，去此三十里。", literal: "\" The attending Hu in fear said: \"He arrived three days ago; thirty li from here.\"", idiomatic: "\" The Hu attendants said in terror, \"He arrived three days ago, thirty li from here.\"" },
  { zh: "」超乃閉侍胡，悉會其吏士三十六人，與共飲，酒酣，因激怒之曰：「卿曹與我俱在絕域，今虜使到才數日，而王廣禮敬即廢。", literal: "\" Chao then shut in the Xiongnu attendants, gathered all his clerks and soldiers, thirty-six men, and drank with them; when wine was deep he roused them, saying: \"You and I are all in a remote land; the barbarian envoys arrived only days ago, yet King Guang's courtesy and respect were at once abandoned.", idiomatic: "\" Chao then shut in the Xiongnu attendants, gathered all his clerks and soldiers—thirty-six men—and drank with them; when the wine had gone deep he roused them, saying, \"You and I are all in a remote land; the barbarian envoys arrived only days ago, yet King Guang's courtesy and respect were at once abandoned." },
  { zh: "如令善阜善收吾屬送匈奴，骸骨長為豺狼食矣。", literal: "If Shanshan should seize our party and hand us to the Xiongnu, our bones would long be food for wolves and jackals.", idiomatic: "If Shanshan should seize our party and hand us to the Xiongnu, our bones would long be food for wolves and jackals." },
  { zh: "為之奈何？", literal: "What is to be done about this?", idiomatic: "What is to be done about this?\"" },
  { zh: "」官屬皆曰：「今在危亡之地，死生從司馬！", literal: "\" The officials all said: \"We are now in a land of peril and ruin—life and death follow the Acting Major!\"", idiomatic: "\" The officials all said, \"We are now in a land of peril and ruin—life and death follow the Acting Major!\"" },
  { zh: "」超曰：「不入虎穴，不得虎子。", literal: "\" Chao said: \"If you do not enter the tiger's den, you cannot get the tiger cub.", idiomatic: "\" Chao said, \"If you do not enter the tiger's den, you cannot get the tiger cub." },
  { zh: "當今之計，獨有因夜以火攻虜，使彼不知我多少，必大震怖，可殄盡也。", literal: "The plan for the present is only to take advantage of night and attack the barbarians with fire, so they will not know how many we are—they will surely be greatly shaken and terrified and can be utterly destroyed.", idiomatic: "The plan for the present is only to take advantage of night and attack the barbarians with fire, so they will not know how many we are—they will surely be greatly shaken and terrified and can be utterly destroyed." },
  { zh: "滅此虜，則善阜善破膽，功成事立矣。", literal: "Destroy these barbarians and Shanshan will lose its gall—merit accomplished, the enterprise established.", idiomatic: "Destroy these barbarians and Shanshan will lose its nerve—merit accomplished, the enterprise established.\"" },
  { zh: "」眾曰：「當與從事議之。", literal: "\" The crowd said: \"We ought to discuss it with the Attending Clerk.\"", idiomatic: "\" The crowd said, \"We ought to discuss it with the Attending Clerk.\"" },
  { zh: "」超怒曰：「吉凶決於今日！", literal: "\" Chao angrily said: \"Fortune and doom are decided today!\"", idiomatic: "\" Chao angrily said, \"Fortune and doom are decided today!\"" },
  { zh: "從事文俗吏，聞此必恐而謀洩，死無所名，非壯士也。", literal: "The Attending Clerk is a civil, conventional official—hear this and he will surely fear and the plot leak; death with no name to leave—no true stalwart.", idiomatic: "The Attending Clerk is a civil, conventional official—hear this and he will surely fear and the plot will leak; to die leaving no name is not the act of a true stalwart." },
  { zh: "」眾曰：「善！", literal: "\" The crowd said: \"Good!\"", idiomatic: "\" The crowd said, \"Good!\"" },
  { zh: "」初夜，超遂將吏士往奔虜營。", literal: "\" At first watch Chao led clerks and soldiers in a rush to the barbarian camp.", idiomatic: "\" At first watch Chao led clerks and soldiers in a rush to the barbarian camp." },
  { zh: "會天大風，超令十人持鼓藏虜捨後，約曰：「見火然，皆當鳴鼓大呼。", literal: "It happened that a great wind arose; Chao ordered ten men to hold drums and hide behind the barbarians' quarters, agreeing: \"When you see fire break out, all must beat drums and shout loudly.", idiomatic: "It happened that a great wind arose; Chao ordered ten men to hold drums and hide behind the barbarians' quarters, agreeing, \"When you see fire break out, all must beat drums and shout loudly." },
  { zh: "」餘人悉持兵弩，夾門而伏，超乃順風縱火。", literal: "\" The rest all held arms and crossbows and lay in ambush flanking the gate; Chao then let fire run with the wind.", idiomatic: "\" The rest all held arms and crossbows and lay in ambush flanking the gate; Chao then let fire run with the wind." },
  { zh: "前後鼓噪，虜眾驚亂。", literal: "Drums and clamor before and behind—the barbarian masses were alarmed and thrown into disorder.", idiomatic: "Drums and clamor before and behind—the barbarian masses were alarmed and thrown into disorder." },
  { zh: "超手格殺三人，吏兵斬其使及從士三十餘級，餘眾百許人悉燒死。", literal: "Chao with his hands struck and killed three men; clerks and soldiers beheaded the envoy and attendants, more than thirty heads; the rest, some hundred-odd men, were all burned to death.", idiomatic: "Chao with his own hands struck and killed three men; clerks and soldiers beheaded the envoy and attendants, more than thirty heads; the rest, some hundred-odd men, were all burned to death." },
  { zh: "明日乃還，告郭恂，恂大驚，既而色動，超知其意，舉手曰：「掾雖不行，班超何心獨擅之乎！", literal: "The next day he returned and reported to Guo Xun; Xun was greatly alarmed, then his expression shifted; Chao knew his thought and raised his hand, saying: \"Though the clerk did not go, how could Ban Chao's heart monopolize the merit alone!\"", idiomatic: "The next day he returned and reported to Guo Xun; Xun was greatly alarmed, then his expression shifted; Chao knew his thought and raised his hand, saying, \"Though the clerk did not go, how could Ban Chao's heart monopolize the merit alone!\"" },
  { zh: "」恂乃悅。", literal: "\" Xun was then pleased.", idiomatic: "\" Xun was then pleased." },
  { zh: "超於是召善阜善王廣，以虜使首示之，一國震怖。", literal: "Chao thereupon summoned King Guang of Shanshan and showed him the barbarian envoys' heads—the whole state trembled in terror.", idiomatic: "Chao thereupon summoned King Guang of Shanshan and showed him the barbarian envoys' heads—the whole state trembled in terror." },
  { zh: "超告以漢威德，「自今以後，勿復與北虜通。", literal: "Chao informed him of Han's authority and virtue: \"From now on, do not again communicate with the northern barbarians.", idiomatic: "Chao informed him of Han's authority and virtue, \"From now on, do not again communicate with the northern barbarians." },
  { zh: "」廣叩頭：「願屬漢，無二心。", literal: "\" Guang knocked his head: \"I wish to belong to Han, with no second heart.", idiomatic: "\" Guang knocked his head and said, \"I wish to belong to Han, with no second heart." },
  { zh: "」遂納子為質。", literal: "\" He thereupon sent his son as hostage.", idiomatic: "\" He thereupon sent his son as hostage." },
  { zh: "還白竇固，固大喜，具上超功效，並求更選使使西域。", literal: "Returning he reported to Dou Gu; Gu was greatly pleased, fully reported Chao's achievements above, and also requested to select another envoy to send to the Western Regions.", idiomatic: "Returning, he reported to Dou Gu; Gu was greatly pleased, fully reported Chao's achievements above, and also requested that another envoy be selected to send to the Western Regions." },
  { zh: "帝曰：「吏如班超，何故不遣，而更選乎！", literal: "The emperor said: \"An official like Ban Chao—why not send him and instead choose another!\"", idiomatic: "The emperor said, \"An official like Ban Chao—why not send him and instead choose another!\"" },
  { zh: "今以超為軍司馬，令遂前功。", literal: "Now make Chao Army Major and order him to continue his former merit.", idiomatic: "Now make Chao Army Major and order him to continue his former merit." },
  { zh: "固復使超使於窴，欲益其兵，超願但將本所從三十六人，曰：「於窴國大而遠，今將數百人，無益於強；", literal: "Gu again sent Chao as envoy to Yutian and wished to increase his troops; Chao wished only to lead the original thirty-six who had followed him, saying: \"Yutian's state is large and far; now to lead several hundred men is of no benefit to strength;", idiomatic: "Gu again sent Chao as envoy to Yutian and wished to increase his troops; Chao wished only to lead the original thirty-six who had followed him, saying, \"Yutian's state is large and far; to lead several hundred men now is of no benefit to strength;" },
  { zh: "如有不虞，多益為累耳。", literal: "if something unforeseen occurs, adding more only becomes a burden.", idiomatic: "if something unforeseen occurs, adding more only becomes a burden.\"" },
  { zh: "」是時於窴王廣德雄張南道，而匈奴遣使監護其國。", literal: "\" At this time King Guangde of Yutian held the southern road in proud sway, and the Xiongnu sent envoys to oversee his state.", idiomatic: "\" At this time King Guangde of Yutian held the southern road in proud sway, and the Xiongnu sent envoys to oversee his state." },
  { zh: "超既至於窴，廣德禮意甚疏。", literal: "When Chao had reached Yutian, Guangde's courtesy and intent were very slight.", idiomatic: "When Chao had reached Yutian, Guangde's courtesy and intent were very slight." },
  { zh: "且其俗信巫，巫言：「神怒，何故欲向漢？", literal: "Moreover their custom trusted shamans; a shaman said: \"The spirits are angry—why do you wish to turn toward Han?", idiomatic: "Moreover their custom trusted shamans; a shaman said, \"The spirits are angry—why do you wish to turn toward Han?" },
  { zh: "漢使有□咼馬，急求取以祠我！", literal: "The Han envoy has a □咼 horse—hurry and seek it to sacrifice to me!", idiomatic: "The Han envoy has a piebald horse—hurry and seek it to sacrifice to me!\"" },
  { zh: "」廣德乃遣國相私來比就超請馬。", literal: "\" Guangde thereupon sent the state chancellor to come in person privately and approach Chao to request the horse.", idiomatic: "\" Guangde thereupon sent the state chancellor to come in person privately and approach Chao to request the horse." },
  { zh: "超密知其狀，報許之，而令巫自來取馬。", literal: "Chao secretly knew the situation, replied that he agreed, but ordered the shaman to come himself to take the horse.", idiomatic: "Chao secretly knew the situation, replied that he agreed, but ordered the shaman to come himself to take the horse." },
  { zh: "有頃，巫至，超即斬其首；", literal: "Before long the shaman arrived; Chao at once cut off his head;", idiomatic: "Before long the shaman arrived; Chao at once cut off his head;" },
  { zh: "收私來比，鞭笞數百。", literal: "seized the one who had come in person and flogged him several hundred strokes.", idiomatic: "seized the chancellor who had come in person and flogged him several hundred strokes." },
  { zh: "以巫首送廣德；", literal: "He sent the shaman's head to Guangde;", idiomatic: "He sent the shaman's head to Guangde;" },
  { zh: "因責讓之。", literal: "and thereby rebuked and reproached him.", idiomatic: "and thereby rebuked and reproached him." },
  { zh: "廣德素聞超在善阜善誅滅虜使，大惶恐，即殺匈奴使者而降。", literal: "Guangde had long heard that Chao at Shanshan executed and destroyed the barbarian envoys; he was greatly fearful and alarmed, at once killed the Xiongnu envoys and surrendered.", idiomatic: "Guangde had long heard that Chao at Shanshan executed and destroyed the barbarian envoys; he was greatly fearful and alarmed, at once killed the Xiongnu envoys and surrendered." },
  { zh: "超重賜其王以下，因鎮撫焉。", literal: "Chao richly rewarded the king and those below, and thereby pacified and settled them.", idiomatic: "Chao richly rewarded the king and those below, and thereby pacified and settled them." },
  { zh: "於是諸國皆遣子入侍，西域與漢絕六十五載，至是乃復通焉。", literal: "Thereupon the various states all sent sons to attend court; the Western Regions and Han had been cut off for sixty-five years—to this time they were again connected.", idiomatic: "Thereupon the various states all sent sons to attend court; the Western Regions and Han had been cut off for sixty-five years—to this time they were again connected." },
  { zh: "超，彪之子也。", literal: "Chao was the son of Biao.", idiomatic: "Chao was the son of Biao." },
  { zh: "淮陽王延，性驕奢，而遇下嚴烈。", literal: "Prince Yan of Huaiyang was by nature arrogant and extravagant, yet toward subordinates severe and harsh.", idiomatic: "Prince Yan of Huaiyang was by nature arrogant and extravagant, yet toward subordinates severe and harsh." },
  { zh: "有上書告「延與姬兄謝弇及姊婿韓光招奸猾，作圖讖，祠祭祝詛。", literal: "Someone submitted a memorial reporting: \"Yan with his concubine's elder brother Xie Yan and his elder sister's son-in-law Han Guang recruited crafty villains, made chart-prophecies, and offered sacrifices with curses and imprecations.", idiomatic: "Someone submitted a memorial reporting that Yan, with his concubine's elder brother Xie Yan and his elder sister's son-in-law Han Guang, recruited crafty villains, made chart-prophecies, and offered sacrifices with curses and imprecations.\"" },
  { zh: "事下案驗。", literal: "The matter was sent down for investigation and verification.", idiomatic: "The matter was sent down for investigation and verification." },
  { zh: "五月，癸丑，弇、光及司徒邢穆皆坐死，所連及死、徙者甚眾。", literal: "In the fifth month, on guichou, Xie Yan, Han Guang, and Minister of Education Xing Mu were all punished with death; those implicated who died or were banished were very numerous.", idiomatic: "In the fifth month, on guichou, Xie Yan, Han Guang, and Minister of Education Xing Mu were all punished with death; those implicated who died or were banished were very numerous." },
  { zh: "戊午晦，日有食之。", literal: "On the last day of the month, wuwu, there was an eclipse of the sun.", idiomatic: "On the last day of the month, wuwu day, there was a solar eclipse." },
  { zh: "六月，丙寅，以大司農西河王敏為司徒。", literal: "In the sixth month, on bingyin, made Grand Minister of Agriculture Wang Min of Xihe Minister of Education.", idiomatic: "In the sixth month, on bingyin, Grand Minister of Agriculture Wang Min of Xihe was made Minister of Education." },
  { zh: "有司奏請誅淮陽王延，上以延罪薄於楚王英，秋，七月，徙延為阜陵王，食二縣。", literal: "The responsible offices memorialized requesting execution of Prince Yan of Huaiyang; the emperor, because Yan's crime was lighter than Prince Ying of Chu's, in autumn, the seventh month, transferred Yan to Prince of Fuling, with revenue from two counties.", idiomatic: "The responsible offices memorialized requesting execution of Prince Yan of Huaiyang; the emperor, because Yan's crime was lighter than Prince Ying of Chu's, in autumn, the seventh month, transferred Yan to Prince of Fuling, with revenue from two counties." },
  { zh: "是歲，北匈奴大入雲中，雲中太守廉范拒之；", literal: "This year the Northern Xiongnu raided deeply into Yunzhong; Administrator of Yunzhong Lian Fan resisted them;", idiomatic: "This year the Northern Xiongnu raided deeply into Yunzhong; Administrator of Yunzhong Lian Fan resisted them;" },
  { zh: "吏以眾少，欲移書傍郡求救，范不許。", literal: "the clerks, because their numbers were few, wished to send documents to neighboring commanderies to seek rescue; Fan would not permit it.", idiomatic: "the clerks, because their numbers were few, wished to send documents to neighboring commanderies to seek rescue; Fan would not permit it." },
  { zh: "會日暮，范令軍士各交縛兩炬，三頭爇火，營中星列。", literal: "It happened to be sunset; Fan ordered the soldiers each to bind two torches crosswise, light fire at three heads—the camp like stars in array.", idiomatic: "It happened to be sunset; Fan ordered the soldiers each to bind two torches crosswise, light fire at three heads—the camp like stars in array." },
  { zh: "虜謂漢兵救至，大驚，待旦將退。", literal: "The barbarians thought Han troops had arrived to rescue and were greatly alarmed; they waited for dawn and were about to withdraw.", idiomatic: "The barbarians thought Han rescue troops had arrived and were greatly alarmed; they waited for dawn and were about to withdraw." },
  { zh: "范令軍中蓐食，晨，往赴之，斬", literal: "Fan ordered the army to take mat-meals; at dawn he went to meet them and beheaded", idiomatic: "Fan ordered the army to take mat-meals; at dawn he went to meet them and beheaded" },
  { zh: "首數百級，虜自相轔藉，死者千餘人，由此不敢復向雲中。", literal: "several hundred heads; the barbarians trampled one another—more than a thousand dead; from this they did not again dare turn toward Yunzhong.", idiomatic: "several hundred heads; the barbarians trampled one another—more than a thousand dead; from this they did not again dare turn toward Yunzhong." },
  { zh: "范，丹之孫也。", literal: "Fan was the grandson of Dan.", idiomatic: "Fan was the grandson of Dan." },
  { zh: "春，正月，上當謁原陵，夜，夢先帝、太后如平生歡，既寤，悲不能寐；", literal: "In spring, the first month, the emperor was to attend Yuanling; at night he dreamed the former emperor and empress dowager as in life in joy; when he awoke he grieved and could not sleep;", idiomatic: "In spring, the first month, the emperor was to attend Yuanling; at night he dreamed the former emperor and empress dowager as in life in joy; when he awoke he grieved and could not sleep;" },
  { zh: "即案歷，明旦日吉，遂率百官上陵。", literal: "he at once examined the calendar—the next day's day was auspicious—and thereupon led the hundred officials to ascend the tomb.", idiomatic: "he at once examined the calendar—the next day was auspicious—and thereupon led the hundred officials to ascend the tomb." },
  { zh: "其日，降甘露於陵樹，帝令百官採取以薦。", literal: "That day sweet dew descended on the tomb trees; the emperor ordered the hundred officials to gather it for offering.", idiomatic: "That day sweet dew descended on the tomb trees; the emperor ordered the hundred officials to gather it for offering." },
  { zh: "會畢，帝從席前伏御床，視太后鏡奩中物，感動悲涕，令易脂澤裝具；", literal: "When the assembly ended the emperor from before the mat prostrated himself on the imperial couch, looked at objects in the empress dowager's mirror casket, was moved and wept in grief, and ordered fresh rouge and adornments replaced;", idiomatic: "When the assembly ended the emperor from before the mat prostrated himself on the imperial couch, looked at objects in the empress dowager's mirror casket, was moved and wept in grief, and ordered fresh rouge and adornments replaced;" },
  { zh: "左右皆泣，莫能仰視。", literal: "those at his sides all wept and none could look up.", idiomatic: "those at his sides all wept and none could look up." },
  { zh: "北海敬王睦薨。", literal: "Prince Mu the Respectful of Beihai died.", idiomatic: "Prince Mu the Respectful of Beihai died." },
  { zh: "睦少好學，光武及上皆愛之，嘗遣中大夫詣京師朝賀，召而謂之曰：「朝廷設問寡人，大夫將何辭以對？", literal: "Mu from youth loved learning; Guangwu and the emperor both cherished him; he was once sent with a Palace Grandee to the capital for New Year congratulations; summoned and told him: \"If the court sets questions to me, what words will the grandee use to reply?", idiomatic: "Mu from youth loved learning; Guangwu and the emperor both cherished him; he was once sent with a Palace Grandee to the capital for New Year congratulations; summoned and told him, \"If the court sets questions to me, what words will the grandee use to reply?" },
  { zh: "」使者曰：「大王忠孝慈仁，敬賢樂士，臣敢不以實對！", literal: "\" The envoy said: \"The great king is loyal, filial, kind, and benevolent, respects the worthy and delights in scholars—your servant dares not reply otherwise than in truth!\"", idiomatic: "\" The envoy said, \"The great king is loyal, filial, kind, and benevolent, respects the worthy and delights in scholars—I dare not reply otherwise than in truth!\"" },
  { zh: "」睦曰：「吁，子危我哉！", literal: "\" Mu said: \"Alas, you endanger me!\"", idiomatic: "\" Mu said, \"Alas, you endanger me!\"" },
  { zh: "此乃孤幼時進趣之行也。", literal: "Those are my youthful pursuits when young.", idiomatic: "Those are my youthful pursuits when young." },
  { zh: "大夫其對以孤襲爵以來，志意衰惰，聲色是娛，犬馬是好，乃為相愛耳。", literal: "Let the grandee reply that since I inherited the fief my will and intent have declined and grown slack, sound and color are my pleasure, dogs and horses are my delight—that is what will show mutual affection.", idiomatic: "Let the grandee reply that since I inherited the fief my will and intent have declined and grown slack, sound and color are my pleasure, dogs and horses are my delight—that is what will show mutual affection.\"" },
  { zh: "」其智慮畏慎如此。", literal: "\" His wisdom and caution were thus.", idiomatic: "\" His wisdom and caution were thus." },
  { zh: "二月，乙巳，司徒王敏薨。", literal: "In the second month, on yisi, Minister of Education Wang Min died.", idiomatic: "In the second month, on yisi, Minister of Education Wang Min died." },
  { zh: "三月，癸丑，以汝南太守鮑昱為司徒。", literal: "In the third month, on guichou, made Administrator of Runan Bao Yu Minister of Education.", idiomatic: "In the third month, on guichou, Administrator of Runan Bao Yu was made Minister of Education." },
  { zh: "昱，永之子也。", literal: "Yu was the son of Yong.", idiomatic: "Yu was the son of Yong." },
  { zh: "益州刺史梁國朱輔宣示漢德，威懷遠夷，自汶山以西，前世所不至，正朔所未加，白狼、槃木等百餘國。", literal: "Inspector of Yi Province Zhu Fu of Liangguo proclaimed Han's virtue; by awesomeness he embraced distant barbarians—from Mount Wen westward, places former ages never reached, where the calendar and regalia had not been applied, the Bailang, Panmu, and more than a hundred states.", idiomatic: "Inspector of Yi Province Zhu Fu of Liangguo proclaimed Han's virtue; by awesomeness he embraced distant barbarians—from Mount Wen westward, places former ages never reached, where the calendar and regalia had not been applied, the Bailang, Panmu, and more than a hundred states." },
  { zh: "皆舉種稱臣奉貢。", literal: "All raised their tribes to style themselves subjects and present tribute.", idiomatic: "All raised their tribes to style themselves subjects and present tribute." },
  { zh: "白狼王唐取作詩三章，歌頌漢德，輔使犍為郡掾由恭譯而獻之。", literal: "King Tang Qu of the Bailang composed three stanzas of verse praising Han's virtue; Fu had You Gong, clerk of Qianwei commandery, translate and present them.", idiomatic: "King Tang Qu of the Bailang composed three stanzas of verse praising Han's virtue; Fu had You Gong, clerk of Qianwei commandery, translate and present them." },
  { zh: "初，龜茲王建為匈奴所立，倚恃虜威，據有北道，攻殺疏勒王，立其臣兜題為疏勒王。", literal: "At first King Jian of Kucha was established by the Xiongnu; relying on barbarian might he held the northern road, attacked and killed the king of Shule, and established his minister Douti as king of Shule.", idiomatic: "At first King Jian of Kucha was established by the Xiongnu; relying on barbarian might he held the northern road, attacked and killed the king of Shule, and established his minister Douti as king of Shule." },
  { zh: "班超從間道至疏勒，去兜題所居槃橐城九十里，逆遣吏田慮先往降之，敕慮曰：「兜題本非疏勒種，國人必不用命；", literal: "Ban Chao by a side road reached Shule, ninety li from Pantuo city where Douti dwelt; he sent ahead Clerk Tian Lü to go first and induce surrender, instructing Lü: \"Douti is originally not of Shule stock—the people will surely not obey his commands;", idiomatic: "Ban Chao by a side road reached Shule, ninety li from Pantuo city where Douti dwelt; he sent ahead Clerk Tian Lü to go first and induce surrender, instructing Lü, \"Douti is originally not of Shule stock—the people will surely not obey his commands;" },
  { zh: "若不即降，便可執之。", literal: "if he does not surrender at once, you may seize him.", idiomatic: "if he does not surrender at once, you may seize him.\"" },
  { zh: "」慮既到，兜題見慮輕弱，殊無降意。", literal: "\" When Lü had arrived, Douti saw Lü was slight and weak and had absolutely no intent to surrender.", idiomatic: "\" When Lü had arrived, Douti saw Lü was slight and weak and had absolutely no intent to surrender." },
  { zh: "慮因其無備，遂前劫縛兜題，左右出其不意，皆驚懼奔走。", literal: "Lü, because he was unprepared, thereupon advanced and seized and bound Douti; those at his sides, caught unawares, all fled in alarm and fear.", idiomatic: "Lü, because Douti was unprepared, thereupon advanced and seized and bound him; those at his sides, caught unawares, all fled in alarm and fear." },
  { zh: "慮馳報超，超即赴之，悉召疏勒將吏，說以龜茲無道之狀，因立其故王兄子忠為王，國人大悅。", literal: "Lü galloped to report to Chao; Chao at once hastened there, summoned all Shule's generals and officials, explained Kucha's lawless conduct, and thereby established the former king's elder brother's son Zhong as king—the state's people were greatly pleased.", idiomatic: "Lü galloped to report to Chao; Chao at once hastened there, summoned all Shule's generals and officials, explained Kucha's lawless conduct, and thereby established the former king's elder brother's son Zhong as king—the state's people were greatly pleased." },
  { zh: "超問忠及官屬：「當殺兜題邪，生遣之邪？", literal: "Chao asked Zhong and the officials: \"Should we kill Douti, or send him away alive?", idiomatic: "Chao asked Zhong and the officials, \"Should we kill Douti, or send him away alive?" },
  { zh: "」鹹曰：「當殺之。", literal: "\" All said: \"He should be killed.\"", idiomatic: "\" All said, \"He should be killed.\"" },
  { zh: "」超曰；", literal: "\" Chao said;", idiomatic: "\" Chao said," },
  { zh: "「殺之無益於事，當令龜茲知漢威德。", literal: "\"To kill him is of no benefit to the affair—we should let Kucha know Han's authority and virtue.", idiomatic: "\"To kill him is of no benefit to the affair—we should let Kucha know Han's authority and virtue." },
  { zh: "」遂解遣之。", literal: "\" He thereupon released and sent him off.", idiomatic: "\" He thereupon released and sent him off." },
  { zh: "夏，五月，戊子，公卿百官以帝威德懷遠，祥物顯應，並集朝堂奉觴上壽。", literal: "In summer, the fifth month, on wuzi, the Excellencies, ministers, and hundred officials, because the emperor's authority and virtue embraced the distant and auspicious things appeared in response, all gathered in the court hall, raised cups, and offered longevity.", idiomatic: "In summer, the fifth month, on wuzi, the Excellencies, ministers, and hundred officials, because the emperor's authority and virtue embraced the distant and auspicious things appeared in response, all gathered in the court hall, raised cups, and offered longevity." },
  { zh: "制曰：「天生神物，以應王者；", literal: "An edict said: \"Heaven produces numinous things to respond to kings;", idiomatic: "An edict said, \"Heaven produces numinous things to respond to kings;" },
  { zh: "遠人慕化，實由有德；", literal: "distant people admire transformation—truly because of possessing virtue;", idiomatic: "distant people admire transformation—truly because of possessing virtue;" },
  { zh: "朕以虛薄，何以享斯！", literal: "I am empty and slight—how can I enjoy this!", idiomatic: "I am empty and slight—how can I enjoy this!" },
  { zh: "唯高祖、光武聖德所被，不敢有辭，其敬舉觴，太常擇吉日策告宗廟。", literal: "Only what Gaozu and Guangwu's sagely virtue overspread—I dare not decline; respectfully raise your cups; the Grand Master of Ceremonies shall choose an auspicious day and report by written proclamation to the ancestral temple.", idiomatic: "Only what Gaozu and Guangwu's sagely virtue overspread—I dare not decline; respectfully raise your cups; the Grand Master of Ceremonies shall choose an auspicious day and report by written proclamation to the ancestral temple." },
  { zh: "」仍推恩賜民爵及粟有差。", literal: "\" He still extended grace and bestowed ranks and grain on the people in varying measure.", idiomatic: "\" He still extended grace and bestowed ranks and grain on the people in varying measure." },
  { zh: "冬，十一月，遣奉車都尉竇固、駙馬都尉耿秉、騎都尉劉張出敦煌崑崙塞，擊西域，秉、張皆去符，傳以屬固，合兵萬四千騎，擊破白山虜於蒲類海上，遂進擊車師。", literal: "In winter, the eleventh month, sent Bearer of the Imperial Carriage Dou Gu, Commandant of the Imperial Son-in-Law Geng Bing, and Commandant of Cavalry Liu Zhang out through Dunhuang and the Kunlun Pass to strike the Western Regions; Bing and Zhang both removed their tallies and passed authority to Gu; combined troops fourteen thousand horse; routed the Baishan barbarians at Pulei Sea and thereupon advanced to strike Cheshi.", idiomatic: "In winter, the eleventh month, Bearer of the Imperial Carriage Dou Gu, Commandant of the Imperial Son-in-Law Geng Bing, and Commandant of Cavalry Liu Zhang were sent out through Dunhuang and the Kunlun Pass to strike the Western Regions; Bing and Zhang both removed their tallies and passed authority to Gu; combined troops numbered fourteen thousand horse; they routed the Baishan barbarians at Pulei Sea and thereupon advanced to strike Cheshi." },
  { zh: "車師前王，即後王之子也，其廷相去五百餘里。", literal: "The Front King of Cheshi was the son of the Rear King; their courts were more than five hundred li apart.", idiomatic: "The Front King of Cheshi was the son of the Rear King; their courts were more than five hundred li apart." },
  { zh: "固以後王道遠，山谷深，士卒寒苦，欲攻前王；", literal: "Gu, because the Rear King's road was far, valleys deep, and soldiers cold and suffering, wished to attack the Front King;", idiomatic: "Gu, because the Rear King's road was far, valleys deep, and soldiers cold and suffering, wished to attack the Front King;" },
  { zh: "秉以為先赴後王，並力根本，則前王自服。", literal: "Bing held that if they first hastened to the Rear King and combined strength at the root, the Front King would submit of himself.", idiomatic: "Bing held that if they first hastened to the Rear King and combined strength at the root, the Front King would submit of himself." },
  { zh: "固計未決，秉奮身而起曰：「請行前。", literal: "Gu's plan was undecided; Bing roused himself and rose, saying: \"I request to go ahead.\"", idiomatic: "Gu's plan was undecided; Bing roused himself and rose, saying, \"I request to go ahead.\"" },
  { zh: "」乃上馬引兵北入，眾軍不得已，並進，斬首數千級。", literal: "\" He thereupon mounted, led troops northward in, and the mass of armies had no choice but to advance together and behead several thousand heads.", idiomatic: "\" He thereupon mounted, led troops northward, and the mass of armies had no choice but to advance together and behead several thousand heads." },
  { zh: "後王安得震怖，走出門迎秉，脫帽，抱馬足降，秉將以詣固；", literal: "The Rear King An was shaken and terrified, went out the gate to meet Bing, removed his cap, embraced the horse's legs and surrendered; Bing was about to bring him to Gu;", idiomatic: "The Rear King An was shaken and terrified, went out the gate to meet Bing, removed his cap, embraced the horse's legs and surrendered; Bing was about to bring him to Gu;" },
  { zh: "其前王亦歸命，遂定車師而還。", literal: "the Front King also submitted; they thereupon settled Cheshi and returned.", idiomatic: "the Front King also submitted; they thereupon settled Cheshi and returned." },
  { zh: "於是固奏復置西域都護及戊、己校尉。", literal: "Thereupon Gu memorialized to restore the Protector of the Western Regions and the Geng and Ji commandants.", idiomatic: "Thereupon Gu memorialized to restore the Protector of the Western Regions and the Geng and Ji commandants." },
  { zh: "以陳睦為都護；", literal: "Chen Mu was made Protector;", idiomatic: "Chen Mu was made Protector;" },
  { zh: "司馬耿恭為戊校尉，屯後王部金蒲城；", literal: "Major Geng Gong was made Colonel of the Wuji Garrison and encamped at Jinpucheng in the Rear King's territory;", idiomatic: "Major Geng Gong was made Colonel of the Wuji Garrison and encamped at Jinpucheng in the Rear King's territory;" },
  { zh: "謁者關寵為己校尉，屯前王部柳中城，屯各置數百人。", literal: "Gentleman-Usher Guan Chong was made Colonel of the Jiyi Garrison and encamped at Liuzhong in the Front King's territory; each garrison was posted with several hundred men.", idiomatic: "Gentleman-Usher Guan Chong was made Colonel of the Jiyi Garrison and encamped at Liuzhong in the Front King's territory; each garrison was posted with several hundred men." },
  { zh: "恭，況之孫也。", literal: "Gong was the grandson of Kuang.", idiomatic: "Gong was the grandson of Geng Kuang." },
  { zh: "春，二月，詔竇固等罷兵還京師。", literal: "In spring, the second month, an edict ordered Dou Gu and the others to dismiss the army and return to the capital.", idiomatic: "In spring, the second month, an edict ordered Dou Gu and the others to dismiss the army and return to the capital." },
  { zh: "北單于遣左鹿蠡王率二萬騎擊車師，耿恭遣司馬將兵三百人救之，皆為所沒，匈奴遂破殺車師後王安得而攻金蒲城。", literal: "The Northern Chanyu sent the Left Luli King with twenty thousand horse to attack Cheshi; Geng Gong sent a major with three hundred troops to rescue them—all were destroyed by the enemy; the Xiongnu thereupon broke and killed the Rear King of Cheshi An De and attacked Jinpucheng.", idiomatic: "The Northern Chanyu sent the Left Luli King with twenty thousand horse to attack Cheshi; Geng Gong sent a major with three hundred troops to rescue them—all were destroyed; the Xiongnu thereupon broke and killed the Rear King of Cheshi An De and attacked Jinpucheng." },
  { zh: "恭以毒藥傅矢，語匈奴曰：「漢家箭神，其中瘡者必有異。", literal: "Gong smeared poison on arrows and told the Xiongnu: \"Han arrows are divine—whoever is struck in the wound will surely have something strange happen.", idiomatic: "Gong smeared poison on the arrows and told the Xiongnu, \"Han arrows are divine—whoever is struck in the wound will surely suffer something strange." },
  { zh: "」虜中矢者，視創皆沸，大驚，會天暴風雨，隨雨擊之，殺傷甚眾；", literal: "\" Among the barbarians those struck by arrows saw their wounds all boil; they were greatly alarmed; just then Heaven sent violent wind and rain, and following the rain they struck them, killing and wounding very many;", idiomatic: "\" Among the barbarians those struck by arrows saw their wounds boil; they were greatly alarmed; just then a violent storm broke, and they struck them amid the rain, killing and wounding very many;" },
  { zh: "匈奴震怖，相謂曰：「漢兵神，真可畏也！", literal: "the Xiongnu were shaken in terror and said to one another: \"Han troops are divine—truly to be feared!", idiomatic: "the Xiongnu were shaken in terror and said to one another, \"Han troops are divine—truly to be feared!\"" },
  { zh: "」遂解去。", literal: "\" They thereupon raised the siege and departed.", idiomatic: "They thereupon raised the siege and departed." },
  { zh: "夏，六月，己未，有星孛於太微。", literal: "In summer, the sixth month, on day jiwei, a comet appeared in the Supreme Palace Enclosure.", idiomatic: "In summer, the sixth month, on jiwei day, a comet appeared in the Supreme Palace Enclosure." },
  { zh: "耿恭以疏勒城傍有澗水可固，引兵據之。", literal: "Geng Gong because beside Shule city there was stream water by which one could make a stand led his troops to occupy it.", idiomatic: "Geng Gong, because stream water beside Shule city could serve for a stand, led his troops to occupy it." },
  { zh: "秋，七月，匈奴復來攻，擁絕澗水；", literal: "In autumn, the seventh month, the Xiongnu came again to attack and blocked off the stream water;", idiomatic: "In autumn, the seventh month, the Xiongnu came again to attack and blocked off the stream water;" },
  { zh: "恭於城中穿井十五丈，不得水，吏士渴乏，至笮馬糞汁而飲之。", literal: "Gong within the city dug a well fifteen zhang deep but obtained no water; officers and soldiers were parched and exhausted, reaching the point of squeezing horse dung for juice to drink.", idiomatic: "Gong dug a well fifteen zhang deep within the city but obtained no water; officers and soldiers were parched and exhausted, reaching the point of squeezing horse dung for juice to drink." },
  { zh: "恭身自率士挽籠，有頃，水泉奔出，眾皆稱萬歲。", literal: "Gong in person led the soldiers to draw with buckets; in a moment a spring burst forth and all cried \"Long live the ten thousand years!\"", idiomatic: "Gong in person led the soldiers to draw with buckets; in a moment a spring burst forth and all cried \"Long live!\"" },
  { zh: "乃令吏士揚水以示虜，虜出不意，以為神明，遂引去。", literal: "He then ordered officers and soldiers to splash water to show the barbarians; the barbarians, not expecting it, took it for divine power and thereupon withdrew.", idiomatic: "He then ordered officers and soldiers to splash water to show the barbarians; the barbarians, not expecting it, took it for divine power and thereupon withdrew." },
  { zh: "八月，壬子，帝崩於東宮前殿，年四十八。", literal: "In the eighth month, on day renzi, the Emperor died in the front hall of the Eastern Palace, aged forty-eight.", idiomatic: "In the eighth month, on renzi day, the Emperor died in the front hall of the Eastern Palace, aged forty-eight." },
  { zh: "遺詔：「無起寢廟，藏主於光烈皇后更衣別室。", literal: "His testamentary edict said: \"Do not raise a sleeping temple; store the spirit tablet in Empress Guanglie's dressing-room side chamber.", idiomatic: "His testamentary edict said, \"Do not raise a sleeping temple; store the spirit tablet in Empress Guanglie's dressing-room side chamber.\"" },
  { zh: "」帝遵奉建武制度，無所變更，后妃之家不得封侯與政。", literal: "\" The Emperor had followed and upheld the Jianwu institutions without any change; families of empresses and consorts were not permitted enfeoffment as marquises or participation in government.", idiomatic: "The Emperor had followed and upheld the Jianwu institutions without change; families of empresses and consorts were not permitted enfeoffment as marquises or participation in government." },
  { zh: "館陶公主為子求郎，不許，而賜錢千萬，謂群臣曰：「郎官上應列宿，出宰百里，苟非其人，則民受其殃，是以難之。", literal: "The Princess of Guantao sought a Gentleman-attendant post for her son; he did not permit it but bestowed ten million cash, saying to the ministers: \"Gentleman-attendants above correspond to the arrayed stars; going out they govern a hundred li—if the man is not right, the people suffer their calamity; that is why it is hard.", idiomatic: "The Princess of Guantao sought a Gentleman-attendant post for her son; he did not permit it but bestowed ten million cash, saying to the ministers, \"Gentleman-attendants above correspond to the arrayed stars; going out they govern a hundred li—if the man is not right, the people suffer calamity; that is why it is hard.\"" },
  { zh: "」公車以反支日不受章奏，帝聞而怪曰：「民廢農桑，遠來詣闕，而復拘以禁忌，豈為政之意乎！", literal: "\" The Imperial Carriage Office on fanzhi days did not accept memorials and reports; the Emperor heard of it and said in wonder: \"The people abandon farming and sericulture and come from afar to the palace gate, yet you again bind them with taboos—is this the intent of government!", idiomatic: "\" The Imperial Carriage Office on fanzhi days did not accept memorials and reports; the Emperor heard of it and said in wonder, \"The people abandon farming and sericulture and come from afar to the palace gate, yet you again bind them with taboos—is this the intent of government!\"" },
  { zh: "」於是遂蠲其制。", literal: "\" He thereupon abolished that regulation.", idiomatic: "He thereupon abolished that regulation." },
  { zh: "尚書閻章二妹為貴人，章精力曉舊典，久次當遷重職，帝為後宮親屬，竟不用。", literal: "Master of Writing Yan Zhang's two younger sisters were Worthy Ladies; Zhang was energetic and understood old regulations; long in rank he ought to have been promoted to a weighty post—the Emperor because he was kin of the rear palace ultimately did not employ him.", idiomatic: "Master of Writing Yan Zhang's two younger sisters were Worthy Ladies; Zhang was energetic and understood old regulations; long in rank he ought to have been promoted to a weighty post—the Emperor, because he was kin of the rear palace, ultimately did not employ him." },
  { zh: "是以吏得其人，民樂其業，遠近畏服，戶口滋殖焉。", literal: "Therefore officials obtained the right men, the people rejoiced in their occupations, far and near feared and submitted, and households and population flourished.", idiomatic: "Therefore officials obtained the right men, the people rejoiced in their occupations, far and near feared and submitted, and households and population flourished." },
  { zh: "太子即位，年十八。", literal: "The heir apparent assumed the throne, aged eighteen.", idiomatic: "The heir apparent assumed the throne, aged eighteen." },
  { zh: "尊皇后曰皇太后。", literal: "The empress was honored as empress dowager.", idiomatic: "The empress was honored as empress dowager." },
  { zh: "明帝初崩，馬氏兄弟爭欲入宮。", literal: "When Emperor Ming had just died, the Ma clan brothers strove to enter the palace.", idiomatic: "When Emperor Ming had just died, the Ma clan brothers strove to enter the palace." },
  { zh: "北宮衛士令楊仁被甲持戟，嚴勒門衛，人莫敢輕進者。", literal: "Commandant of the North Palace Guards Yang Ren donned armor and grasped a halberd, sternly restraining the gate guards—none dared lightly advance.", idiomatic: "Commandant of the North Palace Guards Yang Ren donned armor and grasped a halberd, sternly restraining the gate guards—none dared lightly advance." },
  { zh: "諸馬乃共譖仁於章帝，言其峻刻。", literal: "The various Mas thereupon together slandered Ren to Emperor Zhang, saying he was harsh and severe.", idiomatic: "The various Mas thereupon together slandered Ren to Emperor Zhang, saying he was harsh and severe." },
  { zh: "帝知其忠，愈善之，拜為什邡令。", literal: "The Emperor knew his loyalty and favored him all the more, appointing him Magistrate of Shifang.", idiomatic: "The Emperor knew his loyalty and favored him all the more, appointing him Magistrate of Shifang." },
  { zh: "壬戌，葬孝明皇帝於顯節陵。", literal: "On day renxu Emperor Xiao Ming was buried at Xianjie Mausoleum.", idiomatic: "On renxu day Emperor Xiao Ming was buried at Xianjie Mausoleum." },
  { zh: "冬，十月，丁未，赦天下。", literal: "In winter, the tenth month, on day dingwei, there was an amnesty throughout the realm.", idiomatic: "In winter, the tenth month, on dingwei day, there was an amnesty throughout the realm." },
  { zh: "詔以行太尉事節鄉侯熹為太傅，司空融為太尉，並錄尚書事。", literal: "An edict made Marquis of Jiexiang Xi, acting as Grand Commandant, Grand Tutor, and Minister of Works Rong Grand Commandant, both recording matters of the Masters of Writing.", idiomatic: "An edict made Marquis of Jiexiang Zhao Xi, acting as Grand Commandant, Grand Tutor, and Minister of Works Dou Rong Grand Commandant, both recording matters of the Masters of Writing." },
  { zh: "十一月，戊戌，以蜀郡太守第五倫為司空。", literal: "In the eleventh month, on day wuxu, the Administrator of Shu commandery Diwu Lun was made Minister of Works.", idiomatic: "In the eleventh month, on wuxu day, the Administrator of Shu commandery Diwu Lun was made Minister of Works." },
  { zh: "倫在郡公清，所舉吏多得其人，故帝自遠郡用之。", literal: "Lun in the commandery was fair and pure; those he recommended as clerks mostly were the right men—therefore the Emperor used him from a distant commandery.", idiomatic: "Lun in the commandery was fair and pure; those he recommended as clerks mostly were the right men—therefore the Emperor used him from a distant commandery." },
  { zh: "焉耆、龜茲攻沒都護陳睦，北匈奴圍關寵於柳中城。", literal: "Yanqi and Kucha attacked and destroyed Protector of the Western Regions Chen Mu; the Northern Xiongnu besieged Guan Chong at Liuzhong.", idiomatic: "Yanqi and Kucha attacked and destroyed Protector of the Western Regions Chen Mu; the Northern Xiongnu besieged Guan Chong at Liuzhong." },
  { zh: "會中國有大喪，救兵不至，車師復叛，與匈奴共攻耿恭。", literal: "Just then the central state had a great mourning and relief troops did not arrive; Cheshi rebelled again and with the Xiongnu jointly attacked Geng Gong.", idiomatic: "Just then the central state had a great mourning and relief troops did not arrive; Cheshi rebelled again and with the Xiongnu jointly attacked Geng Gong." },
  { zh: "恭率厲士眾御之，數月，食盡窮困，乃煮鎧弩，食其筋革。", literal: "Gong led and exhorted officers and masses to defend against them; after several months food was exhausted and they were destitute, and they boiled armor and crossbows and ate their sinew and hide.", idiomatic: "Gong led and exhorted officers and troops to defend against them; after several months food was exhausted and they were destitute, and they boiled armor and crossbows and ate their sinew and hide." },
  { zh: "恭與士卒推誠同死生。", literal: "Gong with the soldiers extended sincerity and shared life and death.", idiomatic: "Gong with the soldiers extended sincerity and shared life and death." },
  { zh: "故皆無二心，而稍稍死亡。", literal: "Therefore all had no second heart, yet they gradually died off.", idiomatic: "Therefore all were of one mind, yet they gradually died off." },
  { zh: "餘數十人。", literal: "Only several tens remained.", idiomatic: "Only several tens remained." },
  { zh: "單于知恭已困，欲必降之，遣使招恭曰：「若降者，當封為白屋王。", literal: "The Chanyu knew Gong was already trapped and wished to make him surely submit; he sent envoys to summon Gong, saying: \"If you submit, you shall be enfeoffed as King of the White Dwelling.", idiomatic: "The Chanyu knew Gong was already trapped and wished to make him surely submit; he sent envoys to summon Gong, saying, \"If you submit, you shall be enfeoffed as King of the White Dwelling.\"" },
  { zh: "妻以女子。", literal: "A woman shall be given you as wife.", idiomatic: "A woman shall be given you as wife.\"" },
  { zh: "」恭誘其使上城，手擊殺之，炙諸城上。", literal: "\" Gong lured their envoys up onto the wall, personally struck and killed them, and roasted them on the wall for all to see.", idiomatic: "Gong lured their envoys up onto the wall, personally struck and killed them, and roasted them on the wall for all to see." },
  { zh: "單于大怒，更益兵圍恭，不能下。", literal: "The Chanyu was greatly angered and further increased troops to besiege Gong but could not take him.", idiomatic: "The Chanyu was greatly angered and further increased troops to besiege Gong but could not take him." },
  { zh: "關寵上書求救。", literal: "Guan Chong submitted a memorial seeking rescue.", idiomatic: "Guan Chong submitted a memorial seeking rescue." },
  { zh: "詔公卿會議，司空倫以為不宜救，司徒鮑昱曰：「今使人於危難之地，急而棄之，外則縱蠻夷之暴，內則傷死難之臣，誠令權時，後無邊事可也。", literal: "An edict ordered the excellencies and ministers to meet in council; Minister of Works Lun held that rescue was not fitting; Minister of Education Bao Yu said: \"Now we have sent men into lands of peril and danger—if in urgency we abandon them, outwardly we indulge the violence of barbarians, inwardly we wound ministers who died in hardship; even if for the moment one weighs expedience, afterward there will be no border affairs possible.", idiomatic: "An edict ordered the excellencies and ministers to meet in council; Minister of Works Lun held that rescue was not fitting; Minister of Education Bao Yu said, \"Now we have sent men into lands of peril and danger—if in urgency we abandon them, outwardly we indulge barbarian violence, inwardly we wound ministers who died in hardship; even if for the moment one weighs expedience, afterward there will be no border affairs possible.\"" },
  { zh: "匈奴如復犯塞為寇，陛下將何以使將！", literal: "If the Xiongnu again violate the passes as raiders, how will Your Majesty be able to employ generals!", idiomatic: "If the Xiongnu again violate the passes as raiders, how will Your Majesty be able to employ generals!\"" },
  { zh: "又二部兵人裁各數十，匈奴圍之，歷旬不下，是其寡弱力盡之效也。", literal: "Moreover the troops of the two garrisons number barely several tens each; the Xiongnu besiege them yet for ten days cannot take them—this is the effect of their fewness, weakness, and exhausted strength.", idiomatic: "Moreover the troops of the two garrisons number barely several tens each; the Xiongnu besiege them yet for ten days cannot take them—this is the effect of their fewness, weakness, and exhausted strength." },
  { zh: "可令敦煌、酒泉太守各將精騎二千，多其幡幟，倍道兼行以赴其急；", literal: "One may order the Administrators of Dunhuang and Jiuquan each to lead two thousand picked horse, multiply their banners and flags, and by double marches press on night and day to relieve their urgency;", idiomatic: "One may order the Administrators of Dunhuang and Jiuquan each to lead two thousand picked horse, multiply their banners and flags, and by double marches press on night and day to relieve their urgency;" },
  { zh: "匈奴疲極之兵，必不敢當，四十日間足還入塞。", literal: "the Xiongnu troops, exhausted to the limit, will surely not dare to oppose them; within forty days it is enough to return inside the passes.", idiomatic: "the Xiongnu troops, exhausted to the limit, will surely not dare to oppose them; within forty days it is enough to return inside the passes.\"" },
  { zh: "」帝然之。", literal: "\" The Emperor approved it.", idiomatic: "The Emperor approved it." },
  { zh: "乃遣征西將軍耿秉屯酒泉，行太守事，遣酒泉太守段彭與謁者王蒙、皇甫援發張掖、酒泉、敦煌三郡及善阜善兵合七千餘人以救之。", literal: "He then sent General Who Conquers the West Geng Bing to encamp at Jiuquan and act as Administrator, and sent Jiuquan Administrator Duan Peng with Gentlemen-Usher Wang Meng and Huangfu Yuan to raise troops from Zhangye, Jiuquan, and Dunhuang commanderies and Shanshan forces—more than seven thousand in all—to rescue them.", idiomatic: "He then sent General Who Conquers the West Geng Bing to encamp at Jiuquan and act as Administrator, and sent Jiuquan Administrator Duan Peng with Gentlemen-Usher Wang Meng and Huangfu Yuan to raise troops from Zhangye, Jiuquan, and Dunhuang commanderies and Shanshan forces—more than seven thousand in all—to rescue them." },
  { zh: "甲辰晦，日有食之。", literal: "On the last day of month jiachen there was a solar eclipse.", idiomatic: "On the last day of jiachen month there was a solar eclipse." },
  { zh: "太后兄弟虎賁中郎廖及黃門郎防、光，終明帝世未嘗改官。", literal: "The empress dowager's brothers Huben Central Gentleman Liao and Yellow Gate Gentleman Fang and Guang through Emperor Ming's reign had never had their offices changed.", idiomatic: "The empress dowager's brothers Huben Central Gentleman Liao and Yellow Gate Gentlemen Fang and Guang through Emperor Ming's reign had never had their offices changed." },
  { zh: "帝以廖為衛尉，防為中郎將，光為越騎校尉。", literal: "The Emperor made Liao Commandant of the Guards, Fang Commandant of the Gentlemen, and Guang Colonel of the Yueqi Cavalry.", idiomatic: "The Emperor made Liao Commandant of the Guards, Fang Commandant of the Gentlemen, and Guang Colonel of the Yueqi Cavalry." },
  { zh: "廖等傾身交結，冠蓋之士爭赴趣之。", literal: "Liao and the others threw themselves wholly into forming connections; gentlemen of caps and coaches strove to hurry to them.", idiomatic: "Liao and the others threw themselves wholly into forming connections; gentlemen of caps and coaches strove to hurry to them." },
  { zh: "第五倫上疏曰：「臣聞《書》曰：『臣無作威作福，其害於而家，凶於而國。", literal: "Diwu Lun submitted a memorial, saying: \"Your servant has heard that the Documents says: 'Ministers must not make awesomeness or make blessings—the harm reaches your family, the misfortune reaches your state.", idiomatic: "Diwu Lun submitted a memorial, saying, \"I have heard that the Documents says, 'Ministers must not make awesomeness or make blessings—the harm reaches your family, the misfortune reaches your state.\"" },
  { zh: "』近世光烈皇后雖友愛天至，而抑損陰氏，不假以權勢。", literal: "' In recent times Empress Guanglie, though her friendship and love reached Heaven's utmost, yet restrained and reduced the Yin clan and did not lend them power and influence.", idiomatic: "' In recent times Empress Guanglie, though her friendship and love reached Heaven's utmost, yet restrained and reduced the Yin clan and did not lend them power and influence." },
  { zh: "其後梁、竇之家，互有非法，明帝即位，竟多誅之。", literal: "Afterward the Liang and Dou households each had unlawful acts; when Emperor Ming took the throne he in the end executed many of them.", idiomatic: "Afterward the Liang and Dou households each had unlawful acts; when Emperor Ming took the throne he in the end executed many of them." },
  { zh: "自是雒中無復權戚，書記請托，一皆斷絕。", literal: "From this time in Luoyang there were no more powerful kin; written requests and entreaties were all cut off.", idiomatic: "From this time in Luoyang there were no more powerful kin; written requests and entreaties were all cut off." },
  { zh: "又諭諸外戚曰：『苦身待士，不如為國。", literal: "He also instructed the various maternal kin: 'To toil the body and wait on scholars is not as good as serving the state.", idiomatic: "He also instructed the various maternal kin, 'To toil the body and wait on scholars is not as good as serving the state.\"" },
  { zh: "戴盆望天，事不兩施。", literal: "Wearing a basin on the head while looking at Heaven—two things cannot be done at once.", idiomatic: "Wearing a basin on the head while looking at Heaven—two things cannot be done at once.\"" },
  { zh: "』今之議者，復以馬氏為言。", literal: "' Today's debaters again take the Ma clan as their topic.", idiomatic: "' Today's debaters again take the Ma clan as their topic." },
  { zh: "竊聞衛尉廖以布三千匹，城門校尉防以錢三百萬，私贍三輔衣冠，知與不知，莫不畢給。", literal: "I have heard that Commandant of the Guards Liao with three thousand bolts of cloth and Colonel of the City Gates Fang with three million cash privately supported the caps and robes of the Three Metropolises—whether known to them or not, none failed to receive a full grant.", idiomatic: "I have heard that Commandant of the Guards Liao with three thousand bolts of cloth and Colonel of the City Gates Fang with three million cash privately supported the caps and robes of the Three Metropolises—whether known to them or not, none failed to receive a full grant." },
  { zh: "又聯臘日亦遺其在雒中者錢各五千。", literal: "Moreover on the la festival they also sent those of their kin in Luoyang five thousand cash each.", idiomatic: "Moreover on the la festival they also sent those of their kin in Luoyang five thousand cash each." },
  { zh: "越騎校尉光，臘用羊三百頭，米四百斛，肉五千斤。", literal: "Colonel of the Yueqi Cavalry Guang for the la used three hundred sheep, four hundred hu of grain, and five thousand jin of meat.", idiomatic: "Colonel of the Yueqi Cavalry Guang for the la used three hundred sheep, four hundred hu of grain, and five thousand jin of meat." },
  { zh: "臣愚以為不應經義。", literal: "Your servant in folly holds that this does not accord with canonical meaning.", idiomatic: "I in folly hold that this does not accord with canonical meaning." },
  { zh: "惶恐，不敢不以聞。", literal: "In fear and trembling I dare not fail to report it.", idiomatic: "In fear and trembling I dare not fail to report it." },
  { zh: "陛下情慾厚之，亦宜所以安之。", literal: "Your Majesty's feelings and desires are thick toward them—you also ought thereby to bring them peace.", idiomatic: "Your Majesty's feelings are generous toward them—you also ought thereby to bring them peace." },
  { zh: "臣今言此，誠欲上忠陛下，下全後家也。", literal: "Your servant now speaks this truly wishing above to be loyal to Your Majesty and below to preserve the empress's family.", idiomatic: "I now speak this truly wishing above to be loyal to Your Majesty and below to preserve the empress's family." },
  { zh: "是歲，京師及兗、豫、徐州大旱。", literal: "This year the capital and Yan, Yu, and Xu provinces suffered great drought.", idiomatic: "This year the capital and Yan, Yu, and Xu provinces suffered great drought." },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
